window.EN_CONTENT={"source":"English for Palestine 8 (Pupil's Book 8A و 8B)","meta":{"source":{"8A":"https://elearn.azureedge.net/Books/c8/en8-p1.pdf","8B":"https://elearn.azureedge.net/Books/c8/en8-p2.pdf"},"notes":["Source: official Ministry of Education 'English for Palestine' NEW EDITION Pupil's Book 8A (Units 1-7) and 8B (Units 8-14), served from the Ministry e-learning portal elearn.edu.ps.","Separate Grade 8 Workbook PDFs were NOT found on Ministry sites (elearn.edu.ps, moe.edu.ps); workbook content is therefore not included (unverified/missing).","Also downloaded: 2024 Gaza 'Learning Modules' condensed Pupil's Book 8 (src/gaza-modules-2024.pdf) which renumbers to 12 units (no revision units) – not used for unit order.","Lessons = 'Periods' (12 per unit, one page each); page refs are printed book page numbers (= PDF page numbers).","Units 7 and 14 are both printed as 'Revision 1' in the contents pages."],"gender_note":"gender m/f; gender_verified=false means the book does not state it (Doctor, Assistant)","book_exercises_note":"book_exercises: every numbered activity on every Period page (both Pupil's Books, Units 1-14), with page, period, activity number, instruction, type (classified from the instruction) and items as printed. Items flagged has_blanks keep the book's gaps. Parsed automatically from PDF text; multi-column layouts (picture-description matching, tables) may be scrambled. No answer keys exist in the book."},"units":[{"number":1,"semester":1,"title":"Hello World!","page":4,"pages":[4,15],"revision":false,"vocabulary":[{"word":"at the moment","arabic":"في الوقت الحالي","example":"Nadia's family are living in London at the moment.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"family","arabic":"عائلة","example":"There are four people in the Kamal family.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"go online","arabic":"يدخل على الإنترنت","example":"Sami always goes online in the evening.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"Grandma","arabic":"الجدة","example":"Grandma lives in Jenin.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"landline (phone)","arabic":"هاتف أرضي","example":"Tina tried the landline, but it was busy.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"Mrs","arabic":"السيدة (لقب للمرأة المتزوجة)","example":"Mrs Kamal is in the kitchen.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"Mr","arabic":"السيد","example":"Mr Kamal is watching the sport on TV.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"on the phone","arabic":"على الهاتف","example":"Mum is on the phone to Grandma.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"project","arabic":"مشروع","example":"We need to plan our school project.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"so","arabic":"لذلك","example":"Sami is using the computer, so I can't email you.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"channel","arabic":"قناة","example":"Which channel is the documentary on?","source":"book word box","example_note":"example adapted from the unit text"},{"word":"documentary","arabic":"فيلم وثائقي","example":"There's a TV documentary about Palestine at 7:30.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"forecast","arabic":"توقّع / نشرة (الطقس)","example":"The weather forecast says it will be windy.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"hurricane","arabic":"إعصار","example":"A huge hurricane is coming in our direction.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"information","arabic":"معلومات","example":"You can find that information on the internet.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"like (= such as)","arabic":"مثل","example":"We watch serious programmes like documentaries.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"nationality","arabic":"جنسية","example":"Pele's nationality is Brazilian.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"serious","arabic":"جادّ","example":"She always looks very serious.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"speed","arabic":"سرعة","example":"The car is travelling at a very high speed.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"fishing","arabic":"صيد السمك","example":"Let's go fishing on the lake.","source":"book word box","example_note":"example adapted from the unit text"}],"sentences":["Hello. Nadia speaking.","Listen, we need to plan our school project.","Guess what!","Sami always goes online in the evening.","The hurricanes are getting worse."],"dialogues":[{"title":"Period 1 conversation","page":4,"source":"verbatim from Pupil's Book","lines":[{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Hello. Nadia speaking."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"Hi, Nadia. It's Tina. How are you?"},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Fine, thanks. And you?"},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"I'm fine, too. Listen, we need to plan our school project."},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Right. But why are you calling my mobile? That's expensive."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"I tried your landline, but it was busy."},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Ah, yes. Mum's using the phone in the kitchen to call her mother. Grandma lives in Jenin, and they talk on the phone every week."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"Well, let's email each other."},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Sorry, but we can't at the moment. My brother Sami is using the computer. He's chatting to his friends online."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"Oh, no!"},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Sami always goes online in the evening."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"So let's carry on with your mobile."},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Yes, but not here. Dad's watching the sport on TV."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"Ah, so are you moving to the next room?"},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Yes … But guess what! Mum's finishing."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"So we can change to the landline. Great!"}],"note":"Book has more than two speakers; 'speaker' gives the character. Map to A/B voices by speaker+gender."}],"texts":[{"title":"Living with modern communications","page":8,"paragraphs":["Young World is asking people of different nationalities how modern communications are changing their lives.","Anna, from the USA, says there are lots of bad TV programmes, but the weather forecasts are good. Modern satellites collect better information on the speed and direction of hurricanes, so forecasts are getting better.","Sameer and Hanan, from Palestine, love watching cartoons. But their parents say they can only watch serious programmes like documentaries.","Ali, from Morocco, is a fisherman. He can call different markets from his boat, so he finds the best market for his fish. His mobile is giving his family a better life.","Lyn and Mark live on a big farm in Australia. Their parents gave them mobiles to stay in contact. But now they are always on the phone, and Mum and Dad are getting angry."],"source":"adapted (shortened) from the Pupil's Book reading text"}],"grammar":[{"title":"المضارع البسيط مقابل المضارع المستمر","explanation":"يُستعمل المضارع البسيط للتعبير عن العادات والأفعال المتكرّرة والحقائق الثابتة، ويتكوّن من الفعل في صيغته الأصلية مع إضافة (s/es) للمفرد الغائب. أمّا المضارع المستمر فيُعبّر عن حدثٍ يجري الآن أو في فترةٍ مؤقّتة، ويتكوّن من (am/is/are + الفعل + ing).","examples":["They talk on the phone every week.","Mum is using the phone in the kitchen now.","Grandma lives in Jenin.","Nadia and her family are living in London at the moment."]},{"title":"المضارع المستمر لوصف التغيّر","explanation":"يُستعمل المضارع المستمر أيضًا لوصف أمرٍ يتغيّر تدريجيًّا عبر فترةٍ طويلة، وغالبًا مع أفعال مثل get وgrow وrise وfall.","examples":["The hurricanes are getting worse.","The forecasts are getting better.","The number of mobile phones is rising."]},{"title":"أفعال لا تأتي عادةً في صيغة الاستمرار","explanation":"هناك أفعال تدلّ على الحالة أو الشعور أو المعرفة لا تُستعمل عادةً في صيغة المستمر، مثل: love, like, hate, know, prefer, mean, need, understand, want.","examples":["We understand hurricanes better now.","Sami loves chatting to his friends online."]}],"grammar_en":["Present simple v present continuous","Present continuous for describing change"],"pronunciation":[{"title":"p in pairs of letters – sp, pr, pl","words":["speak","project","plan","play","please"]}],"functions":["using greetings","focussing on a topic of conversation","writing a letter or email"],"writing":["paragraphs"],"task":"Contacting a new pen friend (p15)","seeds":[{"type":"gap_fill","prompt":"Nadia's family are living in London _____.","answer":"at the moment"},{"type":"meaning_mcq","prompt":"at the moment","answer":"في الوقت الحالي","distractors":["مشروع","توقّع / نشرة (الطقس)","إعصار"]},{"type":"gap_fill","prompt":"There are four people in the Kamal _____.","answer":"family"},{"type":"meaning_mcq","prompt":"family","answer":"عائلة","distractors":["السيدة (لقب للمرأة المتزوجة)","على الهاتف","يدخل على الإنترنت"]},{"type":"meaning_mcq","prompt":"go online","answer":"يدخل على الإنترنت","distractors":["الجدة","السيدة (لقب للمرأة المتزوجة)","مشروع"]},{"type":"gap_fill","prompt":"_____ lives in Jenin.","answer":"Grandma"},{"type":"meaning_mcq","prompt":"Grandma","answer":"الجدة","distractors":["جادّ","على الهاتف","إعصار"]},{"type":"gap_fill","prompt":"Tina tried the _____, but it was busy.","answer":"landline"},{"type":"meaning_mcq","prompt":"landline (phone)","answer":"هاتف أرضي","distractors":["في الوقت الحالي","مثل","جنسية"]},{"type":"gap_fill","prompt":"_____ Kamal is in the kitchen.","answer":"Mrs"},{"type":"meaning_mcq","prompt":"Mrs","answer":"السيدة (لقب للمرأة المتزوجة)","distractors":["مثل","إعصار","جنسية"]},{"type":"gap_fill","prompt":"_____ Kamal is watching the sport on TV.","answer":"Mr"},{"type":"meaning_mcq","prompt":"Mr","answer":"السيد","distractors":["صيد السمك","على الهاتف","إعصار"]},{"type":"gap_fill","prompt":"Mum is _____ to Grandma.","answer":"on the phone"},{"type":"meaning_mcq","prompt":"on the phone","answer":"على الهاتف","distractors":["يدخل على الإنترنت","جنسية","مشروع"]},{"type":"gap_fill","prompt":"We need to plan our school _____.","answer":"project"},{"type":"meaning_mcq","prompt":"project","answer":"مشروع","distractors":["في الوقت الحالي","لذلك","جادّ"]},{"type":"gap_fill","prompt":"Sami is using the computer, _____ I can't email you.","answer":"so"},{"type":"meaning_mcq","prompt":"so","answer":"لذلك","distractors":["معلومات","جنسية","إعصار"]},{"type":"gap_fill","prompt":"Which _____ is the documentary on?","answer":"channel"},{"type":"meaning_mcq","prompt":"channel","answer":"قناة","distractors":["الجدة","مشروع","صيد السمك"]},{"type":"gap_fill","prompt":"There's a TV _____ about Palestine at 7:30.","answer":"documentary"},{"type":"meaning_mcq","prompt":"documentary","answer":"فيلم وثائقي","distractors":["يدخل على الإنترنت","إعصار","سرعة"]},{"type":"gap_fill","prompt":"The weather _____ says it will be windy.","answer":"forecast"},{"type":"meaning_mcq","prompt":"forecast","answer":"توقّع / نشرة (الطقس)","distractors":["الجدة","عائلة","قناة"]},{"type":"gap_fill","prompt":"A huge _____ is coming in our direction.","answer":"hurricane"},{"type":"meaning_mcq","prompt":"hurricane","answer":"إعصار","distractors":["على الهاتف","يدخل على الإنترنت","جنسية"]},{"type":"gap_fill","prompt":"You can find that _____ on the internet.","answer":"information"},{"type":"meaning_mcq","prompt":"information","answer":"معلومات","distractors":["جادّ","السيد","هاتف أرضي"]},{"type":"gap_fill","prompt":"We watch serious programmes _____ documentaries.","answer":"like"},{"type":"meaning_mcq","prompt":"like (= such as)","answer":"مثل","distractors":["يدخل على الإنترنت","سرعة","عائلة"]},{"type":"gap_fill","prompt":"Pele's _____ is Brazilian.","answer":"nationality"},{"type":"meaning_mcq","prompt":"nationality","answer":"جنسية","distractors":["مثل","السيد","هاتف أرضي"]},{"type":"gap_fill","prompt":"She always looks very _____.","answer":"serious"},{"type":"meaning_mcq","prompt":"serious","answer":"جادّ","distractors":["صيد السمك","معلومات","سرعة"]},{"type":"gap_fill","prompt":"The car is travelling at a very high _____.","answer":"speed"},{"type":"meaning_mcq","prompt":"speed","answer":"سرعة","distractors":["لذلك","جادّ","فيلم وثائقي"]},{"type":"gap_fill","prompt":"Let's go _____ on the lake.","answer":"fishing"},{"type":"meaning_mcq","prompt":"fishing","answer":"صيد السمك","distractors":["إعصار","هاتف أرضي","السيدة (لقب للمرأة المتزوجة)"]},{"type":"grammar_reorder","grammar":"المضارع البسيط مقابل المضارع المستمر","answer":"They talk on the phone every week.","tokens":["talk","week","on","the","They","every","phone"]},{"type":"grammar_reorder","grammar":"المضارع البسيط مقابل المضارع المستمر","answer":"Mum is using the phone in the kitchen now.","tokens":["phone","is","Mum","now","the","the","using","kitchen","in"]},{"type":"grammar_reorder","grammar":"المضارع المستمر لوصف التغيّر","answer":"The hurricanes are getting worse.","tokens":["hurricanes","The","getting","are","worse"]},{"type":"grammar_reorder","grammar":"المضارع المستمر لوصف التغيّر","answer":"The forecasts are getting better.","tokens":["getting","The","better","forecasts","are"]},{"type":"grammar_reorder","grammar":"أفعال لا تأتي عادةً في صيغة الاستمرار","answer":"We understand hurricanes better now.","tokens":["We","better","understand","now","hurricanes"]},{"type":"grammar_reorder","grammar":"أفعال لا تأتي عادةً في صيغة الاستمرار","answer":"Sami loves chatting to his friends online.","tokens":["loves","his","online","Sami","to","friends","chatting"]},{"type":"dialogue_order","lines":["Hello. Nadia speaking.","Hi, Nadia. It's Tina. How are you?","Fine, thanks. And you?","I'm fine, too. Listen, we need to plan our school project.","Right. But why are you calling my mobile? That's expensive.","I tried your landline, but it was busy."]}],"verified":true,"notes":"Vocabulary words, dialogues and grammar points verified against the PDF; Arabic meanings/explanations authored; examples drawn or adapted from the unit text."},{"number":2,"semester":1,"title":"A taste of Palestinian culture","page":16,"pages":[16,27],"revision":false,"vocabulary":[{"word":"age","arabic":"عمر / سنّ","example":"I started playing the tablah at the age of four.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"culture","arabic":"ثقافة","example":"Mike and Tina are enjoying their first taste of Arab culture.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"develop","arabic":"يتطوّر","example":"Modern guitars developed from the 'oud long ago.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"feel like","arabic":"يرغب في","example":"It's exciting music. I feel like dancing!","source":"book word box","example_note":"example adapted from the unit text"},{"word":"guitar","arabic":"غيتار","example":"That 'oud sounds like a guitar.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"pizza","arabic":"بيتزا","example":"This looks like a pizza, but it's sfeeha.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"quite","arabic":"إلى حدّ ما / تمامًا","example":"He could play the 'oud quite well at 18.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"seem","arabic":"يبدو","example":"You seem to know a lot about the 'oud.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"sound","arabic":"يبدو (من الصوت)","example":"That drum music sounds great.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"taste","arabic":"طعم / يتذوّق","example":"The kebabs taste delicious.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"tasty","arabic":"لذيذ","example":"This cake is very tasty.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"classical","arabic":"كلاسيكي","example":"Classical Arab music developed many centuries ago.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"folk song","arabic":"أغنية شعبية","example":"People used to sing folk songs about their simple lives.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"instrument","arabic":"آلة موسيقية","example":"The 'oud is a very important instrument.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"feeling","arabic":"شعور","example":"Music tells our feelings.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"poem","arabic":"قصيدة","example":"I love the poems of Mahmoud Darwish.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"rock music","arabic":"موسيقى الروك","example":"Rock music developed in America in the 1950s.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"the heart of","arabic":"قلب / جوهر","example":"Music is at the heart of life.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"the 1950s","arabic":"الخمسينيات","example":"Rock music started in the 1950s.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"used to","arabic":"اعتاد أن (في الماضي)","example":"People used to sing folk songs.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"musician","arabic":"موسيقي (عازف)","example":"Tariq wants to be a musician.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"singer","arabic":"مغنٍّ","example":"Oum Kalthoum was a great singer.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"song","arabic":"أغنية","example":"He sings old songs at weddings.","source":"book word box","example_note":"example adapted from the unit text"}],"sentences":["I feel like dancing!","You're the best!","They taste delicious, too.","I could play it quite well at the age of 18.","People used to sing folk songs about their simple lives."],"dialogues":[{"title":"Period 1 conversation","page":16,"source":"verbatim from Pupil's Book","lines":[{"speaker":"Tina","gender":"f","gender_verified":true,"text":"This looks good. It looks like a pizza."},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"But it isn't. It's sfeeha."},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"And here's the next thing – kebabs."},{"speaker":"Mike","gender":"m","gender_verified":true,"text":"They smell delicious."},{"speaker":"Mrs Kamal","gender":"f","gender_verified":true,"text":"They taste delicious, too. Everyone, please start."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"Can you cook Arab food, Nadia?"},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"I can make things like kebabs, but I can't cook a big meal."},{"speaker":"Mike","gender":"m","gender_verified":true,"text":"Listen! That drum music sounds great. Is it Arab?"},{"speaker":"Mr Kamal","gender":"m","gender_verified":true,"text":"Yes, that drum is a tablah. … And now you can hear an 'oud."},{"speaker":"Mike","gender":"m","gender_verified":true,"text":"That 'oud sounds like a guitar, Mr Kamal. Is it?"},{"speaker":"Mr Kamal","gender":"m","gender_verified":true,"text":"Well, modern guitars developed from the 'oud long ago."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"It's exciting music. I feel like dancing!"},{"speaker":"Mrs Kamal","gender":"f","gender_verified":true,"text":"I'm not surprised. You see, it's a wedding dance."},{"speaker":"Mike","gender":"m","gender_verified":true,"text":"You seem to know a lot about the 'oud, Mr Kamal. Do you play it, too?"},{"speaker":"Mr Kamal","gender":"m","gender_verified":true,"text":"I could play it quite well at the age of 18, but not now. Work got busy, so I couldn't find time to play."},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"But Dad, you still play at parties, and you're the best!"}],"note":"Book has more than two speakers; 'speaker' gives the character. Map to A/B voices by speaker+gender."}],"texts":[{"title":"Arab music","page":20,"paragraphs":["Music is at the heart of life. We dance to music, and music tells our feelings. It can make us sad or happy, and it can even make us feel better when we are sick.","Thousands of years ago, people used to sing folk songs about their simple lives. Much modern music came from these songs, like rock music in America in the 1950s.","Classical Arab music developed many centuries ago from folk music and poems. Singing was very important, and people still love great singers like Oum Kalthoum and Farid Al-Atrash.","Many people agree that the greatest Arab instrument is the 'oud. Musicians developed the modern 'oud about a thousand years ago. In Europe, the modern guitar developed from it."],"source":"adapted (shortened) from the Pupil's Book reading text"}],"grammar":[{"title":"أفعال الحواسّ والحالة","explanation":"تُستعمل الأفعال look, smell, taste, sound, feel, seem في المضارع البسيط للتعبير عن الانطباع، ويتبعها صفة، أو like + اسم، أو (seem + to + فعل).","examples":["This sfeeha looks good.","The kebabs smell delicious.","That drum music sounds great.","That 'oud sounds like a guitar.","You seem to know a lot about the 'oud."]},{"title":"can / could للتعبير عن القدرة","explanation":"تُستعمل can للقدرة في الحاضر وcould للقدرة في الماضي، ويأتي بعدهما الفعل في صيغته الأصلية دون to. والنفي: can't / couldn't.","examples":["I can make kebabs, but I can't cook a big meal.","I could play quite well when I was young.","Work got busy, so I couldn't find time to play."]},{"title":"used to للعادات في الماضي","explanation":"تُستعمل (used to + الفعل) للتعبير عن فعلٍ كان يتكرّر في الماضي ولم يعد يحدث. في السؤال والنفي نستعمل did / didn't + use to (دون d).","examples":["People used to sing folk songs.","Did people use to play the guitar thousands of years ago?","He didn't use to do that before."]}],"grammar_en":["Stative verbs (look, smell, taste, sound, seem, feel)","can / could for ability","Past simple vs used to for repeated actions"],"pronunciation":[{"title":"strong sounds in longer words","words":[]}],"functions":["talking about ability","talking about habitual action in the past","telling the story of a special person"],"writing":["making notes to write paragraphs"],"task":"Telling the story of a special person (p27)","seeds":[{"type":"gap_fill","prompt":"I started playing the tablah at the _____ of four.","answer":"age"},{"type":"meaning_mcq","prompt":"age","answer":"عمر / سنّ","distractors":["شعور","اعتاد أن (في الماضي)","قصيدة"]},{"type":"gap_fill","prompt":"Mike and Tina are enjoying their first taste of Arab _____.","answer":"culture"},{"type":"meaning_mcq","prompt":"culture","answer":"ثقافة","distractors":["شعور","يرغب في","اعتاد أن (في الماضي)"]},{"type":"gap_fill","prompt":"Modern guitars _____ed from the 'oud long ago.","answer":"develop"},{"type":"meaning_mcq","prompt":"develop","answer":"يتطوّر","distractors":["يرغب في","لذيذ","غيتار"]},{"type":"gap_fill","prompt":"It's exciting music. I _____ dancing!","answer":"feel like"},{"type":"meaning_mcq","prompt":"feel like","answer":"يرغب في","distractors":["ثقافة","يتطوّر","أغنية"]},{"type":"gap_fill","prompt":"That 'oud sounds like a _____.","answer":"guitar"},{"type":"meaning_mcq","prompt":"guitar","answer":"غيتار","distractors":["يرغب في","قلب / جوهر","أغنية شعبية"]},{"type":"gap_fill","prompt":"This looks like a _____, but it's sfeeha.","answer":"pizza"},{"type":"meaning_mcq","prompt":"pizza","answer":"بيتزا","distractors":["غيتار","قلب / جوهر","موسيقى الروك"]},{"type":"gap_fill","prompt":"He could play the 'oud _____ well at 18.","answer":"quite"},{"type":"meaning_mcq","prompt":"quite","answer":"إلى حدّ ما / تمامًا","distractors":["غيتار","موسيقي (عازف)","يتطوّر"]},{"type":"gap_fill","prompt":"You _____ to know a lot about the 'oud.","answer":"seem"},{"type":"meaning_mcq","prompt":"seem","answer":"يبدو","distractors":["إلى حدّ ما / تمامًا","عمر / سنّ","غيتار"]},{"type":"gap_fill","prompt":"That drum music _____s great.","answer":"sound"},{"type":"meaning_mcq","prompt":"sound","answer":"يبدو (من الصوت)","distractors":["كلاسيكي","آلة موسيقية","أغنية"]},{"type":"gap_fill","prompt":"The kebabs _____ delicious.","answer":"taste"},{"type":"meaning_mcq","prompt":"taste","answer":"طعم / يتذوّق","distractors":["اعتاد أن (في الماضي)","يرغب في","لذيذ"]},{"type":"gap_fill","prompt":"This cake is very _____.","answer":"tasty"},{"type":"meaning_mcq","prompt":"tasty","answer":"لذيذ","distractors":["أغنية شعبية","كلاسيكي","عمر / سنّ"]},{"type":"gap_fill","prompt":"_____ Arab music developed many centuries ago.","answer":"classical"},{"type":"meaning_mcq","prompt":"classical","answer":"كلاسيكي","distractors":["مغنٍّ","موسيقى الروك","إلى حدّ ما / تمامًا"]},{"type":"gap_fill","prompt":"People used to sing _____s about their simple lives.","answer":"folk song"},{"type":"meaning_mcq","prompt":"folk song","answer":"أغنية شعبية","distractors":["ثقافة","موسيقي (عازف)","اعتاد أن (في الماضي)"]},{"type":"gap_fill","prompt":"The 'oud is a very important _____.","answer":"instrument"},{"type":"meaning_mcq","prompt":"instrument","answer":"آلة موسيقية","distractors":["بيتزا","لذيذ","شعور"]},{"type":"gap_fill","prompt":"Music tells our _____s.","answer":"feeling"},{"type":"meaning_mcq","prompt":"feeling","answer":"شعور","distractors":["قصيدة","يرغب في","يتطوّر"]},{"type":"gap_fill","prompt":"I love the _____s of Mahmoud Darwish.","answer":"poem"},{"type":"meaning_mcq","prompt":"poem","answer":"قصيدة","distractors":["إلى حدّ ما / تمامًا","موسيقي (عازف)","يبدو"]},{"type":"gap_fill","prompt":"_____ developed in America in the 1950s.","answer":"rock music"},{"type":"meaning_mcq","prompt":"rock music","answer":"موسيقى الروك","distractors":["قصيدة","غيتار","أغنية شعبية"]},{"type":"gap_fill","prompt":"Music is at _____ life.","answer":"the heart of"},{"type":"meaning_mcq","prompt":"the heart of","answer":"قلب / جوهر","distractors":["يرغب في","اعتاد أن (في الماضي)","شعور"]},{"type":"gap_fill","prompt":"Rock music started in _____.","answer":"the 1950s"},{"type":"meaning_mcq","prompt":"the 1950s","answer":"الخمسينيات","distractors":["مغنٍّ","غيتار","شعور"]},{"type":"gap_fill","prompt":"People _____ sing folk songs.","answer":"used to"},{"type":"meaning_mcq","prompt":"used to","answer":"اعتاد أن (في الماضي)","distractors":["موسيقى الروك","يتطوّر","قصيدة"]},{"type":"gap_fill","prompt":"Tariq wants to be a _____.","answer":"musician"},{"type":"meaning_mcq","prompt":"musician","answer":"موسيقي (عازف)","distractors":["الخمسينيات","أغنية شعبية","كلاسيكي"]},{"type":"gap_fill","prompt":"Oum Kalthoum was a great _____.","answer":"singer"},{"type":"meaning_mcq","prompt":"singer","answer":"مغنٍّ","distractors":["شعور","يبدو","ثقافة"]},{"type":"gap_fill","prompt":"He sings old _____s at weddings.","answer":"song"},{"type":"meaning_mcq","prompt":"song","answer":"أغنية","distractors":["إلى حدّ ما / تمامًا","ثقافة","شعور"]},{"type":"grammar_reorder","grammar":"أفعال الحواسّ والحالة","answer":"This sfeeha looks good.","tokens":["looks","This","sfeeha","good"]},{"type":"grammar_reorder","grammar":"أفعال الحواسّ والحالة","answer":"The kebabs smell delicious.","tokens":["delicious","kebabs","smell","The"]},{"type":"grammar_reorder","grammar":"can / could للتعبير عن القدرة","answer":"I can make kebabs, but I can't cook a big meal.","tokens":["big","meal","can't","cook","I","a","but","make","can","kebabs,","I"]},{"type":"grammar_reorder","grammar":"can / could للتعبير عن القدرة","answer":"I could play quite well when I was young.","tokens":["I","could","I","play","well","was","when","young","quite"]},{"type":"grammar_reorder","grammar":"used to للعادات في الماضي","answer":"People used to sing folk songs.","tokens":["sing","to","songs","used","People","folk"]},{"type":"grammar_reorder","grammar":"used to للعادات في الماضي","answer":"Did people use to play the guitar thousands of years ago?","tokens":["use","thousands","play","years","of","to","the","people","Did","guitar","ago"]},{"type":"dialogue_order","lines":["This looks good. It looks like a pizza.","But it isn't. It's sfeeha.","And here's the next thing – kebabs.","They smell delicious.","They taste delicious, too. Everyone, please start.","Can you cook Arab food, Nadia?"]}],"verified":true,"notes":"Vocabulary words, dialogues and grammar points verified against the PDF; Arabic meanings/explanations authored; examples drawn or adapted from the unit text."},{"number":3,"semester":1,"title":"Going to a national park","page":28,"pages":[28,39],"revision":false,"vocabulary":[{"word":"entrance","arabic":"مدخل","example":"They have just arrived at the entrance.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"far","arabic":"بعيد","example":"Is it still very far?","source":"book word box","example_note":"example adapted from the unit text"},{"word":"go camping","arabic":"يذهب للتخييم","example":"We could go camping in the mountains.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"go hiking","arabic":"يذهب للمشي في الطبيعة","example":"Let's go hiking.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"hear of","arabic":"يسمع عن","example":"I've never heard of Yosemite.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"national","arabic":"وطني / قومي","example":"Yosemite is a beautiful national park.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"pass","arabic":"يمرّ بـ / يتجاوز","example":"We've already passed the sign for Yosemite.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"so (= very)","arabic":"جدًّا","example":"You're so slow, Adnan!","source":"book word box","example_note":"example adapted from the unit text"},{"word":"trip","arabic":"رحلة","example":"We went on a school trip last year.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"campsite","arabic":"مخيّم (موقع تخييم)","example":"We're staying at a campsite in the mountains.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"cut down","arabic":"يقطع (الأشجار)","example":"People started cutting down the trees.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"damage","arabic":"يُتلف / يضرّ","example":"Millions of cars damage the park.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"every","arabic":"كل","example":"Thousands of volunteers help every summer.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"go white water rafting","arabic":"يمارس التجديف في المياه السريعة","example":"Last Saturday, we went white water rafting.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"join","arabic":"ينضمّ","example":"Young volunteers join together to help.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"volunteer","arabic":"متطوّع","example":"Thousands of young volunteers help Yosemite.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"waterfall","arabic":"شلّال","example":"Yosemite has the highest waterfalls in America.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"wildlife","arabic":"الحياة البرية","example":"The wildlife is amazing.","source":"book word box","example_note":"example adapted from the unit text"}],"sentences":["Have you ever been there?","I've never heard of Yosemite.","You're so slow!","Look! We're here!","We've already eaten them!"],"dialogues":[{"title":"Period 1 conversation","page":28,"source":"verbatim from Pupil's Book","lines":[{"speaker":"Uncle","gender":"m","gender_verified":true,"text":"Where would you like to go, everyone?"},{"speaker":"Aunt","gender":"f","gender_verified":true,"text":"We could go camping in the mountains."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"Yes, let's find a beautiful lake and stay there."},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"And let's go hiking."},{"speaker":"Uncle","gender":"m","gender_verified":true,"text":"Mountains … lakes … hiking … This means Yosemite!"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"I'm sorry, but I've never heard of Yosemite."},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"It's a beautiful national park. Have you ever seen pictures of it?"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"No, I haven't. It sounds fantastic. Have you ever been there?"},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"Yes, we have. We went on a school trip last year."},{"speaker":"Uncle","gender":"m","gender_verified":true,"text":"And I often used to go hiking there."},{"speaker":"Aunt","gender":"f","gender_verified":true,"text":"Has everyone put their things in the car yet?"},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"Yes, I've just done that."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"And I'm taking my things out now."},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"I'll come soon, but I haven't found my trainers yet."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"You're so slow, Adnan! Omar, let's help him. Then we can leave."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"We're getting hungry, Dad! Is it still very far?"},{"speaker":"Uncle","gender":"m","gender_verified":true,"text":"No, we've already passed the sign for Yosemite."},{"speaker":"Aunt","gender":"f","gender_verified":true,"text":"You can eat the sandwiches in the bag next to your feet."},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"No, we can't. We've already eaten them!"},{"speaker":"Uncle","gender":"m","gender_verified":true,"text":"Look! We're here! There are the mountains!"}],"note":"Book has more than two speakers; 'speaker' gives the character. Map to A/B voices by speaker+gender."}],"texts":[{"title":"Yosemite","page":32,"paragraphs":["Yosemite is an amazing place in America. It has mountains, valleys, lakes, rivers and the highest waterfalls in America. Some of its trees are 90 metres tall.","When people started cutting down the trees, the United States made Yosemite a National Park in 1890. Today, millions of visitors and cars damage it, so it still needs help.","Tony Ross works for Young Friends of Yosemite. His group has been there for three weeks. They clean the campsites and keep the paths safe. They have become great friends, and last Saturday they went white water rafting."],"source":"adapted (shortened) from the Pupil's Book reading text"}],"grammar":[{"title":"المضارع التامّ مع just, yet, already","explanation":"يتكوّن المضارع التامّ من (have/has + التصريف الثالث للفعل)، ويربط الماضي بالحاضر. just تعني (للتوّ) وتأتي قبل التصريف الثالث، وalready تعني (بالفعل/مسبقًا)، وyet تأتي في آخر الجملة المنفية أو السؤال بمعنى (بعد/حتى الآن).","examples":["Yes, I've just done that.","We've already passed the sign for Yosemite.","I haven't found my trainers yet.","Has everyone put their things in the car yet?"]},{"title":"Have you ever …? للتجارب","explanation":"نسأل عن التجارب في الحياة بـ (Have you ever + التصريف الثالث؟)، ونستعمل never للنفي.","examples":["Have you ever been there?","I've never heard of Yosemite."]},{"title":"for و since مع المضارع التامّ","explanation":"تُستعمل for مع مدّة زمنية (for three weeks)، وsince مع نقطة بداية في الزمن (since 1890).","examples":["My group have been here for three weeks.","This has protected Yosemite since then."]}],"grammar_en":["Present perfect with just, yet, already","Present perfect with be & stative verbs + for / since"],"pronunciation":[{"title":"intonation in yes / no questions","words":[]}],"functions":["talking about experiences: Have you ever …?","writing a page of your diary"],"writing":["writing a diary"],"task":"Writing a page of your diary","seeds":[{"type":"gap_fill","prompt":"They have just arrived at the _____.","answer":"entrance"},{"type":"meaning_mcq","prompt":"entrance","answer":"مدخل","distractors":["الحياة البرية","كل","ينضمّ"]},{"type":"gap_fill","prompt":"Is it still very _____?","answer":"far"},{"type":"meaning_mcq","prompt":"far","answer":"بعيد","distractors":["كل","ينضمّ","يسمع عن"]},{"type":"gap_fill","prompt":"We could _____ in the mountains.","answer":"go camping"},{"type":"meaning_mcq","prompt":"go camping","answer":"يذهب للتخييم","distractors":["شلّال","يذهب للمشي في الطبيعة","وطني / قومي"]},{"type":"gap_fill","prompt":"Let's _____.","answer":"go hiking"},{"type":"meaning_mcq","prompt":"go hiking","answer":"يذهب للمشي في الطبيعة","distractors":["يمرّ بـ / يتجاوز","يذهب للتخييم","رحلة"]},{"type":"meaning_mcq","prompt":"hear of","answer":"يسمع عن","distractors":["مخيّم (موقع تخييم)","ينضمّ","يمارس التجديف في المياه السريعة"]},{"type":"gap_fill","prompt":"Yosemite is a beautiful _____ park.","answer":"national"},{"type":"meaning_mcq","prompt":"national","answer":"وطني / قومي","distractors":["يذهب للمشي في الطبيعة","مخيّم (موقع تخييم)","يسمع عن"]},{"type":"gap_fill","prompt":"We've already _____ed the sign for Yosemite.","answer":"pass"},{"type":"meaning_mcq","prompt":"pass","answer":"يمرّ بـ / يتجاوز","distractors":["مخيّم (موقع تخييم)","الحياة البرية","يسمع عن"]},{"type":"gap_fill","prompt":"You're _____ slow, Adnan!","answer":"so"},{"type":"meaning_mcq","prompt":"so (= very)","answer":"جدًّا","distractors":["ينضمّ","رحلة","وطني / قومي"]},{"type":"gap_fill","prompt":"We went on a school _____ last year.","answer":"trip"},{"type":"meaning_mcq","prompt":"trip","answer":"رحلة","distractors":["جدًّا","الحياة البرية","يمارس التجديف في المياه السريعة"]},{"type":"gap_fill","prompt":"We're staying at a _____ in the mountains.","answer":"campsite"},{"type":"meaning_mcq","prompt":"campsite","answer":"مخيّم (موقع تخييم)","distractors":["الحياة البرية","متطوّع","يذهب للمشي في الطبيعة"]},{"type":"meaning_mcq","prompt":"cut down","answer":"يقطع (الأشجار)","distractors":["جدًّا","يمرّ بـ / يتجاوز","وطني / قومي"]},{"type":"gap_fill","prompt":"Millions of cars _____ the park.","answer":"damage"},{"type":"meaning_mcq","prompt":"damage","answer":"يُتلف / يضرّ","distractors":["شلّال","يذهب للمشي في الطبيعة","يمارس التجديف في المياه السريعة"]},{"type":"gap_fill","prompt":"Thousands of volunteers help _____ summer.","answer":"every"},{"type":"meaning_mcq","prompt":"every","answer":"كل","distractors":["يذهب للمشي في الطبيعة","يمارس التجديف في المياه السريعة","بعيد"]},{"type":"meaning_mcq","prompt":"go white water rafting","answer":"يمارس التجديف في المياه السريعة","distractors":["وطني / قومي","ينضمّ","متطوّع"]},{"type":"gap_fill","prompt":"Young volunteers _____ together to help.","answer":"join"},{"type":"meaning_mcq","prompt":"join","answer":"ينضمّ","distractors":["بعيد","يسمع عن","مدخل"]},{"type":"gap_fill","prompt":"Thousands of young _____s help Yosemite.","answer":"volunteer"},{"type":"meaning_mcq","prompt":"volunteer","answer":"متطوّع","distractors":["يمرّ بـ / يتجاوز","رحلة","بعيد"]},{"type":"gap_fill","prompt":"Yosemite has the highest _____s in America.","answer":"waterfall"},{"type":"meaning_mcq","prompt":"waterfall","answer":"شلّال","distractors":["يذهب للمشي في الطبيعة","ينضمّ","جدًّا"]},{"type":"gap_fill","prompt":"The _____ is amazing.","answer":"wildlife"},{"type":"meaning_mcq","prompt":"wildlife","answer":"الحياة البرية","distractors":["مخيّم (موقع تخييم)","يذهب للتخييم","متطوّع"]},{"type":"grammar_reorder","grammar":"المضارع التامّ مع just, yet, already","answer":"Yes, I've just done that.","tokens":["that","done","Yes,","just","I've"]},{"type":"grammar_reorder","grammar":"المضارع التامّ مع just, yet, already","answer":"We've already passed the sign for Yosemite.","tokens":["the","passed","Yosemite","for","sign","already","We've"]},{"type":"grammar_reorder","grammar":"Have you ever …? للتجارب","answer":"Have you ever been there?","tokens":["ever","you","there","been","Have"]},{"type":"grammar_reorder","grammar":"Have you ever …? للتجارب","answer":"I've never heard of Yosemite.","tokens":["never","Yosemite","of","I've","heard"]},{"type":"grammar_reorder","grammar":"for و since مع المضارع التامّ","answer":"My group have been here for three weeks.","tokens":["here","weeks","for","My","three","group","have","been"]},{"type":"grammar_reorder","grammar":"for و since مع المضارع التامّ","answer":"This has protected Yosemite since then.","tokens":["protected","has","Yosemite","since","This","then"]},{"type":"dialogue_order","lines":["Where would you like to go, everyone?","We could go camping in the mountains.","Yes, let's find a beautiful lake and stay there.","And let's go hiking.","Mountains … lakes … hiking … This means Yosemite!","I'm sorry, but I've never heard of Yosemite."]}],"verified":true,"notes":"Vocabulary words, dialogues and grammar points verified against the PDF; Arabic meanings/explanations authored; examples drawn or adapted from the unit text."},{"number":4,"semester":1,"title":"How to get healthy","page":40,"pages":[40,51],"revision":false,"vocabulary":[{"word":"fit","arabic":"لائق بدنيًّا","example":"Get fit and healthy.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"get on","arabic":"يتقدّم / يسير (في أمر ما)","example":"How have you been getting on?","source":"book word box","example_note":"example adapted from the unit text"},{"word":"had better","arabic":"من الأفضل أن","example":"You'd better read this book.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"junk food","arabic":"الوجبات السريعة غير الصحية","example":"Fries are junk food!","source":"book word box","example_note":"example adapted from the unit text"},{"word":"just (= only)","arabic":"فقط","example":"I eat just fries for lunch.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"miss","arabic":"يفوّت","example":"I've been missing breakfast.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"real","arabic":"حقيقي","example":"You need to start eating real food.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"Really?","arabic":"حقًّا؟","example":"Really? Fruit and vegetables?","source":"book word box","example_note":"example adapted from the unit text"},{"word":"recently","arabic":"مؤخّرًا","example":"I haven't been playing well recently.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"wake up","arabic":"يستيقظ","example":"I've been waking up late.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"awake","arabic":"مستيقظ","example":"Coffee keeps you awake.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"exercise","arabic":"تمرين رياضي","example":"Do more exercise.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"go on","arabic":"يستمرّ","example":"When you're tired, you'd better not go on.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"instead (of)","arabic":"بدلًا من","example":"Your body can use fat instead of bread and rice.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"put on weight","arabic":"يزداد وزنه","example":"You've been putting on weight.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"something","arabic":"شيء ما","example":"Do something quiet before bed.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"study","arabic":"يدرس","example":"I've been studying late every night.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"test","arabic":"اختبار","example":"I'm studying for a big test.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"healthy","arabic":"صحّي","example":"I feel much healthier now.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"unhealthy","arabic":"غير صحّي","example":"This can be unhealthy and dangerous.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"dislike","arabic":"يكره / لا يحبّ","example":"I dislike junk food.","source":"book word box","example_note":"example adapted from the unit text"}],"sentences":["What's wrong? You don't look very well.","You'd better read this book.","Really well.","I've been sleeping much better.","What about walking for an hour every day?"],"dialogues":[{"title":"Period 1 conversation","page":40,"source":"verbatim from Pupil's Book","lines":[{"speaker":"Doctor","gender":"m","gender_verified":false,"text":"What's wrong, Sami? You don't look very well."},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"You're right. I've been feeling quite sick for several weeks. And I've been getting tired quickly."},{"speaker":"Doctor","gender":"m","gender_verified":false,"text":"Have you been sleeping badly for a long time, too?"},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"Yes, I have. And I haven't been playing well for my football team recently."},{"speaker":"Doctor","gender":"m","gender_verified":false,"text":"Have you been eating normally?"},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"Well, no. I've been waking up late, and missing breakfast."},{"speaker":"Doctor","gender":"m","gender_verified":false,"text":"So you've been going to school tired and hungry. And what have you been eating for lunch?"},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"Just fries."},{"speaker":"Doctor","gender":"m","gender_verified":false,"text":"Sami, fries are junk food! You need to start eating real food! And that includes fruit and vegetables."},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"Really?"},{"speaker":"Doctor","gender":"m","gender_verified":false,"text":"Yes. And you'd better read this book – Get fit and healthy. Do what it says, and then come back next month."},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"Thanks. I'll do that. I mustn't lose my place in the team!"},{"speaker":"Doctor","gender":"m","gender_verified":false,"text":"How have you been getting on since our talk last month?"},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"Really well. I read the book, and I've been doing what it says since then. I've been sleeping much better."},{"speaker":"Doctor","gender":"m","gender_verified":false,"text":"I can see that. You don't look tired today. Have you been eating better, too?"},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"Yes, and I feel much healthier now. Thanks for all your help."}],"note":"Book has more than two speakers; 'speaker' gives the character. Map to A/B voices by speaker+gender."}],"texts":[{"title":"The healthy living quiz","page":44,"paragraphs":["You have been putting on weight, and you want to lose some. Missing meals is bad for you. Stopping bread and rice can be unhealthy. The best way is to do more exercise, like walking for an hour every day.","You have been studying late and drinking coffee to stay awake, but you can't sleep. You'd better stop drinking coffee late, finish work earlier and do something quiet before bed."],"source":"adapted (shortened) from the Pupil's Book reading text"}],"grammar":[{"title":"المضارع التامّ المستمر","explanation":"يتكوّن من (have/has + been + الفعل + ing)، ويُعبّر عن فعلٍ بدأ في الماضي واستمرّ حتى الآن، وغالبًا مع for وsince.","examples":["I've been feeling quite sick for several weeks.","Have you been sleeping badly?","I've been doing what it says since then."]},{"title":"النصيحة والاقتراح","explanation":"للنصيحة نستعمل: had better ('d better) + الفعل، وshould. وللاقتراح: What about + فعل بـ ing؟ ونفي had better هو had better not.","examples":["You'd better read this book.","You'd better not do this.","What about walking for an hour every day?"]},{"title":"have to / should / must والنفي","explanation":"must وhave to للإلزام، وmustn't للمنع (لا يجوز)، أمّا don't have to فتعني عدم الضرورة، وshouldn't تعني (لا ينبغي).","examples":["I mustn't lose my place in the team!","We have to practise more.","They don't have to hide their feelings."]}],"grammar_en":["Present perfect continuous & action verbs + for / since","Advice / suggestion with What about, had better","have to / should / must + negative forms"],"pronunciation":[{"title":"intonation in wh- questions and suggestions","words":[]}],"functions":["giving advice","making suggestions","sharing problems, suggestions and advice"],"writing":["make notes about feelings"],"task":"Sharing problems and advice","seeds":[{"type":"gap_fill","prompt":"Get _____ and healthy.","answer":"fit"},{"type":"meaning_mcq","prompt":"fit","answer":"لائق بدنيًّا","distractors":["صحّي","تمرين رياضي","مستيقظ"]},{"type":"meaning_mcq","prompt":"get on","answer":"يتقدّم / يسير (في أمر ما)","distractors":["مؤخّرًا","اختبار","يدرس"]},{"type":"meaning_mcq","prompt":"had better","answer":"من الأفضل أن","distractors":["فقط","غير صحّي","الوجبات السريعة غير الصحية"]},{"type":"gap_fill","prompt":"Fries are _____!","answer":"junk food"},{"type":"meaning_mcq","prompt":"junk food","answer":"الوجبات السريعة غير الصحية","distractors":["يفوّت","يكره / لا يحبّ","مؤخّرًا"]},{"type":"gap_fill","prompt":"I eat _____ fries for lunch.","answer":"just"},{"type":"meaning_mcq","prompt":"just (= only)","answer":"فقط","distractors":["تمرين رياضي","حقًّا؟","يزداد وزنه"]},{"type":"gap_fill","prompt":"I've been _____ing breakfast.","answer":"miss"},{"type":"meaning_mcq","prompt":"miss","answer":"يفوّت","distractors":["حقيقي","يكره / لا يحبّ","فقط"]},{"type":"gap_fill","prompt":"You need to start eating _____ food.","answer":"real"},{"type":"meaning_mcq","prompt":"real","answer":"حقيقي","distractors":["شيء ما","يتقدّم / يسير (في أمر ما)","يكره / لا يحبّ"]},{"type":"gap_fill","prompt":"_____ Fruit and vegetables?","answer":"Really?"},{"type":"meaning_mcq","prompt":"Really?","answer":"حقًّا؟","distractors":["غير صحّي","مستيقظ","يزداد وزنه"]},{"type":"gap_fill","prompt":"I haven't been playing well _____.","answer":"recently"},{"type":"meaning_mcq","prompt":"recently","answer":"مؤخّرًا","distractors":["يزداد وزنه","غير صحّي","يستمرّ"]},{"type":"meaning_mcq","prompt":"wake up","answer":"يستيقظ","distractors":["غير صحّي","يدرس","يستمرّ"]},{"type":"gap_fill","prompt":"Coffee keeps you _____.","answer":"awake"},{"type":"meaning_mcq","prompt":"awake","answer":"مستيقظ","distractors":["اختبار","يفوّت","يستيقظ"]},{"type":"gap_fill","prompt":"Do more _____.","answer":"exercise"},{"type":"meaning_mcq","prompt":"exercise","answer":"تمرين رياضي","distractors":["مؤخّرًا","يدرس","فقط"]},{"type":"gap_fill","prompt":"When you're tired, you'd better not _____.","answer":"go on"},{"type":"meaning_mcq","prompt":"go on","answer":"يستمرّ","distractors":["مؤخّرًا","يدرس","اختبار"]},{"type":"gap_fill","prompt":"Your body can use fat _____ of bread and rice.","answer":"instead"},{"type":"meaning_mcq","prompt":"instead (of)","answer":"بدلًا من","distractors":["صحّي","اختبار","يستيقظ"]},{"type":"meaning_mcq","prompt":"put on weight","answer":"يزداد وزنه","distractors":["حقيقي","غير صحّي","اختبار"]},{"type":"gap_fill","prompt":"Do _____ quiet before bed.","answer":"something"},{"type":"meaning_mcq","prompt":"something","answer":"شيء ما","distractors":["يستمرّ","فقط","يدرس"]},{"type":"gap_fill","prompt":"I've been _____ing late every night.","answer":"study"},{"type":"meaning_mcq","prompt":"study","answer":"يدرس","distractors":["شيء ما","الوجبات السريعة غير الصحية","يستيقظ"]},{"type":"gap_fill","prompt":"I'm studying for a big _____.","answer":"test"},{"type":"meaning_mcq","prompt":"test","answer":"اختبار","distractors":["يستمرّ","يتقدّم / يسير (في أمر ما)","غير صحّي"]},{"type":"meaning_mcq","prompt":"healthy","answer":"صحّي","distractors":["تمرين رياضي","يدرس","يستيقظ"]},{"type":"gap_fill","prompt":"This can be _____ and dangerous.","answer":"unhealthy"},{"type":"meaning_mcq","prompt":"unhealthy","answer":"غير صحّي","distractors":["تمرين رياضي","يستمرّ","لائق بدنيًّا"]},{"type":"gap_fill","prompt":"I _____ junk food.","answer":"dislike"},{"type":"meaning_mcq","prompt":"dislike","answer":"يكره / لا يحبّ","distractors":["غير صحّي","فقط","لائق بدنيًّا"]},{"type":"grammar_reorder","grammar":"المضارع التامّ المستمر","answer":"I've been feeling quite sick for several weeks.","tokens":["I've","quite","been","for","feeling","several","sick","weeks"]},{"type":"grammar_reorder","grammar":"المضارع التامّ المستمر","answer":"Have you been sleeping badly?","tokens":["been","Have","sleeping","badly","you"]},{"type":"grammar_reorder","grammar":"النصيحة والاقتراح","answer":"You'd better read this book.","tokens":["better","book","this","read","You'd"]},{"type":"grammar_reorder","grammar":"النصيحة والاقتراح","answer":"You'd better not do this.","tokens":["You'd","better","do","not","this"]},{"type":"grammar_reorder","grammar":"have to / should / must والنفي","answer":"I mustn't lose my place in the team!","tokens":["my","place","team","mustn't","lose","in","I","the"]},{"type":"grammar_reorder","grammar":"have to / should / must والنفي","answer":"We have to practise more.","tokens":["We","have","to","practise","more"]},{"type":"dialogue_order","lines":["What's wrong, Sami? You don't look very well.","You're right. I've been feeling quite sick for several weeks. And I've been getting tired quickly.","Have you been sleeping badly for a long time, too?","Yes, I have. And I haven't been playing well for my football team recently.","Have you been eating normally?","Well, no. I've been waking up late, and missing breakfast."]}],"verified":true,"notes":"Vocabulary words, dialogues and grammar points verified against the PDF; Arabic meanings/explanations authored; examples drawn or adapted from the unit text."},{"number":5,"semester":1,"title":"People and games","page":52,"pages":[52,63],"revision":false,"vocabulary":[{"word":"club","arabic":"نادٍ","example":"I've got training at the club today.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"coach","arabic":"مدرّب","example":"Our coach says we mustn't miss it.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"either","arabic":"أيضًا (في النفي)","example":"I mustn't miss my training, either.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"miss","arabic":"يفتقد","example":"I really miss football!","source":"book word box","example_note":"example adapted from the unit text"},{"word":"practise","arabic":"يتمرّن","example":"We have to practise more.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"soccer","arabic":"كرة القدم (أمريكيًّا)","example":"It's soccer here in America.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"sports bag","arabic":"حقيبة رياضية","example":"Whose is that sports bag?","source":"book word box","example_note":"example adapted from the unit text"},{"word":"training","arabic":"تدريب","example":"Yasmeen has training today.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"whose","arabic":"لمن","example":"Whose is that sports bag?","source":"book word box","example_note":"example adapted from the unit text"},{"word":"compete","arabic":"يتنافس","example":"Teams compete hard to win.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"everything","arabic":"كل شيء","example":"The rules make everything clear.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"everywhere","arabic":"في كل مكان","example":"People everywhere understand football.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"invent","arabic":"يخترع","example":"They invented the modern game in 1863.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"kick","arabic":"يركل","example":"Players often kicked each other.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"part","arabic":"جزء","example":"Games are an important part of school life.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"proud","arabic":"فخور","example":"Everyone is proud and excited.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"rule","arabic":"قاعدة / قانون","example":"Now there are clear rules.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"somewhere","arabic":"في مكان ما","example":"Someone somewhere is scoring a goal.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"competition","arabic":"منافسة / مسابقة","example":"Our school won the football competition.","source":"book word box","example_note":"example adapted from the unit text"}],"sentences":["Whose is that sports bag?","It's hers. Mine is over there.","I really miss football!","I don't, either.","Ours will be much better than theirs!"],"dialogues":[{"title":"Period 1 conversation","page":52,"source":"verbatim from Pupil's Book","lines":[{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Whose is that sports bag, Adnan? Is it yours, or is it Yasmeen's?"},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"It's hers. Mine is over there by the stairs."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"Yes, I've got training at the club today. Our coach says we really mustn't miss it. We have to practise more."},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"I mustn't miss my training, either. You see, Omar, our teams both have big matches tomorrow."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"What kind of sport do you mean? Basketball? Volleyball?"},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"No, soccer."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Soccer? What's that? I've never heard of it."},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"Oh, yes, it's soccer here in America, but everyone else calls it football."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Ah, football! I love the game."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"I do, too."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"But football isn't a game for girls, is it? Not like volleyball."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"I don't agree."},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"I don't, either. Lots of girls play it here."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"It's a game for everyone, and it's my favourite."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Mine, too. I really miss football!"},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"What about training with me this evening?"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Fantastic! And can I come and watch your match tomorrow?"},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"Yes, it'll be good. Our team are going to win!"},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"Ha! You should come and watch our game, Omar. Ours will be much better than theirs!"}],"note":"Book has more than two speakers; 'speaker' gives the character. Map to A/B voices by speaker+gender."}],"texts":[{"title":"People and games","page":56,"paragraphs":["People have been playing team games since ancient times. They love to be part of a team, to compete and to win.","In the past, football had no clear rules. Hundreds of people sometimes played for days, and players often kicked each other more than the ball. In 1863, players from different teams decided the rules together and invented the modern game.","Today, football is the world's favourite sport. Many people think sport makes us better people, so games are an important part of school life.","In 1934, Palestine was the top team from Asia in the World Cup. Since then, the 6th of April has become Palestine's National Sports Day."],"source":"adapted (shortened) from the Pupil's Book reading text"}],"grammar":[{"title":"صفات الملكية وضمائر الملكية","explanation":"صفات الملكية (my, your, his, her, our, their) تأتي قبل الاسم، أمّا ضمائر الملكية (mine, yours, his, hers, ours, theirs) فتحلّ محلّ الاسم. ونسأل عن المالك بـ Whose.","examples":["Whose is that sports bag?","It's hers. Mine is over there by the stairs.","Ours will be much better than theirs!"]},{"title":"too و either","explanation":"تُستعمل too للموافقة في الجمل المثبتة، وeither للموافقة في الجمل المنفية، وتأتيان في آخر الجملة.","examples":["Yasmeen: I do, too.","I mustn't miss my training, either.","I don't, either."]},{"title":"someone / something / somewhere / everyone / everything / everywhere","explanation":"some- تعني (شخص/شيء/مكان ما)، وevery- تعني (كلّ الناس/كلّ شيء/كلّ مكان)، وتأتي مع فعلٍ مفرد.","examples":["Someone somewhere in the world is scoring a goal.","People everywhere understand it.","Everything is clear to everyone."]}],"grammar_en":["Possessive adjectives & possessive pronouns","too / either","someone / something / somewhere, everyone / everything / everywhere"],"pronunciation":[{"title":"showing interest with intonation","words":[]}],"functions":["talking about ownership","writing a true story"],"writing":["write a story"],"task":"Writing a true story","seeds":[{"type":"gap_fill","prompt":"I've got training at the _____ today.","answer":"club"},{"type":"meaning_mcq","prompt":"club","answer":"نادٍ","distractors":["كل شيء","كرة القدم (أمريكيًّا)","يتنافس"]},{"type":"gap_fill","prompt":"Our _____ says we mustn't miss it.","answer":"coach"},{"type":"meaning_mcq","prompt":"coach","answer":"مدرّب","distractors":["نادٍ","فخور","كل شيء"]},{"type":"gap_fill","prompt":"I mustn't miss my training, _____.","answer":"either"},{"type":"meaning_mcq","prompt":"either","answer":"أيضًا (في النفي)","distractors":["يتنافس","فخور","كل شيء"]},{"type":"gap_fill","prompt":"I really _____ football!","answer":"miss"},{"type":"meaning_mcq","prompt":"miss","answer":"يفتقد","distractors":["كل شيء","يركل","قاعدة / قانون"]},{"type":"gap_fill","prompt":"We have to _____ more.","answer":"practise"},{"type":"meaning_mcq","prompt":"practise","answer":"يتمرّن","distractors":["فخور","أيضًا (في النفي)","قاعدة / قانون"]},{"type":"gap_fill","prompt":"It's _____ here in America.","answer":"soccer"},{"type":"meaning_mcq","prompt":"soccer","answer":"كرة القدم (أمريكيًّا)","distractors":["فخور","في كل مكان","يتمرّن"]},{"type":"gap_fill","prompt":"Whose is that _____?","answer":"sports bag"},{"type":"meaning_mcq","prompt":"sports bag","answer":"حقيبة رياضية","distractors":["يفتقد","يخترع","فخور"]},{"type":"gap_fill","prompt":"Yasmeen has _____ today.","answer":"training"},{"type":"meaning_mcq","prompt":"training","answer":"تدريب","distractors":["يخترع","قاعدة / قانون","يركل"]},{"type":"gap_fill","prompt":"_____ is that sports bag?","answer":"whose"},{"type":"meaning_mcq","prompt":"whose","answer":"لمن","distractors":["حقيبة رياضية","في مكان ما","كرة القدم (أمريكيًّا)"]},{"type":"gap_fill","prompt":"Teams _____ hard to win.","answer":"compete"},{"type":"meaning_mcq","prompt":"compete","answer":"يتنافس","distractors":["يتمرّن","في مكان ما","مدرّب"]},{"type":"gap_fill","prompt":"The rules make _____ clear.","answer":"everything"},{"type":"meaning_mcq","prompt":"everything","answer":"كل شيء","distractors":["أيضًا (في النفي)","يتنافس","حقيبة رياضية"]},{"type":"gap_fill","prompt":"People _____ understand football.","answer":"everywhere"},{"type":"meaning_mcq","prompt":"everywhere","answer":"في كل مكان","distractors":["يتمرّن","يركل","لمن"]},{"type":"gap_fill","prompt":"They _____ed the modern game in 1863.","answer":"invent"},{"type":"meaning_mcq","prompt":"invent","answer":"يخترع","distractors":["حقيبة رياضية","يفتقد","نادٍ"]},{"type":"gap_fill","prompt":"Players often _____ed each other.","answer":"kick"},{"type":"meaning_mcq","prompt":"kick","answer":"يركل","distractors":["مدرّب","فخور","حقيبة رياضية"]},{"type":"gap_fill","prompt":"Games are an important _____ of school life.","answer":"part"},{"type":"meaning_mcq","prompt":"part","answer":"جزء","distractors":["كل شيء","منافسة / مسابقة","نادٍ"]},{"type":"gap_fill","prompt":"Everyone is _____ and excited.","answer":"proud"},{"type":"meaning_mcq","prompt":"proud","answer":"فخور","distractors":["نادٍ","منافسة / مسابقة","يتمرّن"]},{"type":"gap_fill","prompt":"Now there are clear _____s.","answer":"rule"},{"type":"meaning_mcq","prompt":"rule","answer":"قاعدة / قانون","distractors":["يتنافس","منافسة / مسابقة","نادٍ"]},{"type":"gap_fill","prompt":"Someone _____ is scoring a goal.","answer":"somewhere"},{"type":"meaning_mcq","prompt":"somewhere","answer":"في مكان ما","distractors":["مدرّب","حقيبة رياضية","كل شيء"]},{"type":"gap_fill","prompt":"Our school won the football _____.","answer":"competition"},{"type":"meaning_mcq","prompt":"competition","answer":"منافسة / مسابقة","distractors":["كل شيء","أيضًا (في النفي)","يركل"]},{"type":"grammar_reorder","grammar":"صفات الملكية وضمائر الملكية","answer":"Whose is that sports bag?","tokens":["Whose","bag","sports","is","that"]},{"type":"grammar_reorder","grammar":"صفات الملكية وضمائر الملكية","answer":"It's hers. Mine is over there by the stairs.","tokens":["the","there","It's","over","by","stairs","Mine","is","hers."]},{"type":"grammar_reorder","grammar":"too و either","answer":"Yasmeen: I do, too.","tokens":["do,","Yasmeen:","I","too"]},{"type":"grammar_reorder","grammar":"too و either","answer":"I mustn't miss my training, either.","tokens":["mustn't","either","miss","I","my","training,"]},{"type":"grammar_reorder","grammar":"someone / something / somewhere / everyone / everything / everywhere","answer":"Someone somewhere in the world is scoring a goal.","tokens":["goal","the","in","a","scoring","is","somewhere","Someone","world"]},{"type":"grammar_reorder","grammar":"someone / something / somewhere / everyone / everything / everywhere","answer":"People everywhere understand it.","tokens":["it","understand","everywhere","People"]},{"type":"dialogue_order","lines":["Whose is that sports bag, Adnan? Is it yours, or is it Yasmeen's?","It's hers. Mine is over there by the stairs.","Yes, I've got training at the club today. Our coach says we really mustn't miss it. We have to practise more.","I mustn't miss my training, either. You see, Omar, our teams both have big matches tomorrow.","What kind of sport do you mean? Basketball? Volleyball?","No, soccer."]}],"verified":true,"notes":"Vocabulary words, dialogues and grammar points verified against the PDF; Arabic meanings/explanations authored; examples drawn or adapted from the unit text."},{"number":6,"semester":1,"title":"Friends","page":64,"pages":[64,75],"revision":false,"vocabulary":[{"word":"alone","arabic":"وحيد / بمفرده","example":"Leave me alone!","source":"book word box","example_note":"example adapted from the unit text"},{"word":"embarrassed","arabic":"محرَج","example":"I always feel bad and embarrassed.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"horrible","arabic":"فظيع / سيّئ جدًّا","example":"I was horrible back to you.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"in fact","arabic":"في الحقيقة","example":"In fact, they shouldn't hide them.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"natural","arabic":"طبيعي","example":"It was only natural, so don't worry.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"scared","arabic":"خائف","example":"I was really scared.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"support","arabic":"يدعم / يساند","example":"You were trying to support me.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"worried","arabic":"قلق","example":"Tina was worried about Tim.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"adult","arabic":"شخص بالغ","example":"You should tell an adult immediately.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"at first","arabic":"في البداية","example":"At first, he may be angry.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"completely","arabic":"تمامًا","example":"We can trust each other completely.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"danger","arabic":"خطر","example":"Perhaps he'll understand the danger.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"dangerous","arabic":"خطير","example":"He's planning to do something dangerous.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"if","arabic":"إذا","example":"If you talk, he'll understand.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"immediately","arabic":"فورًا","example":"Tell an adult immediately.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"secret","arabic":"سرّ","example":"We tell each other all our secrets.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"situation","arabic":"موقف / وضع","example":"I've been in the same situation.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"trust","arabic":"يثق / ثقة","example":"You can never break his trust.","source":"book word box","example_note":"example adapted from the unit text"}],"sentences":["Don't worry.","It's fine. I understand completely.","Leave me alone!","In fact, they shouldn't hide them.","If I do that, I'll lose my best friend."],"dialogues":[{"title":"Period 1 conversation","page":64,"source":"verbatim from Pupil's Book","lines":[{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Hi, Tina. What's the news from the hospital? How's Tim?"},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"He was much better when we visited him last night."},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Great! And you look happier now. You were very upset yesterday morning."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"Yes, I was really scared."},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Well, it's fantastic that you don't need to worry now."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"Listen, Nadia, I want to say sorry for yesterday."},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Oh, because you shouted, 'Leave me alone!'"},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"Yes. I know you were just trying to support me like a good friend."},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Well, I always want to help when a friend is upset."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"And I was horrible back to you! I'm really sorry."},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"It was only natural, so don't worry. Really."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"You see, I sometimes say the wrong thing when I get upset. And when I think about it later, I always feel bad – and embarrassed, too."},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"It's fine. I understood completely, and I wasn't angry."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"Thanks, Nadia."},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"You see, when people are friends, they don't have to hide their feelings. In fact, they shouldn't hide them."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"You really are a good friend, Nadia!"}],"note":"Book has more than two speakers; 'speaker' gives the character. Map to A/B voices by speaker+gender."}],"texts":[{"title":"Help, everyone! What should I do?","page":68,"paragraphs":["My best friend and I tell each other all our secrets. We can trust each other completely. But he is planning to do something dangerous, and it may hurt other people. Should I tell his parents? If I do, I'll lose my best friend.","Karen says: You really should tell his parents. Tom says: If you talk to him, perhaps he'll understand the danger. Alice says: Never break his trust. Alan says: Tell an adult you both trust, like a teacher. At first he may be angry, but in the end you may become even better friends."],"source":"adapted (shortened) from the Pupil's Book reading text"}],"grammar":[{"title":"When / If + المضارع البسيط، + المضارع البسيط أو الأفعال الناقصة","explanation":"تُستعمل هذه الصيغة للحقائق العامّة والقواعد والنصائح: الشرط في المضارع البسيط وجواب الشرط في المضارع البسيط أو مع should/must/have to.","examples":["When people are friends, they don't have to hide their feelings.","I always want to help when a friend is upset.","If you're tired, you should go to bed."]},{"title":"الجملة الشرطية من النوع الأوّل","explanation":"تتكوّن من (If + المضارع البسيط، + will / won't + الفعل) للحديث عن نتيجةٍ محتملة في المستقبل.","examples":["If I do that, I'll lose my best friend.","If you talk, perhaps he'll understand the danger better.","If he's a real friend, he'll understand."]}],"grammar_en":["When / If + present simple, + present simple including modals for rules, obligation, necessity","When / If + present simple, + present tense including modals for suggestions, advice","Conditional Type 1: if + present simple, + will (not)"],"pronunciation":[],"functions":["making suggestions","making things clear (you see, …, In fact, …)","writing a new problem letter and an answer to it"],"writing":["topic sentences"],"task":"Writing a problem letter and an answer","seeds":[{"type":"gap_fill","prompt":"Leave me _____!","answer":"alone"},{"type":"meaning_mcq","prompt":"alone","answer":"وحيد / بمفرده","distractors":["طبيعي","موقف / وضع","في الحقيقة"]},{"type":"gap_fill","prompt":"I always feel bad and _____.","answer":"embarrassed"},{"type":"meaning_mcq","prompt":"embarrassed","answer":"محرَج","distractors":["خطر","شخص بالغ","يثق / ثقة"]},{"type":"gap_fill","prompt":"I was _____ back to you.","answer":"horrible"},{"type":"meaning_mcq","prompt":"horrible","answer":"فظيع / سيّئ جدًّا","distractors":["في الحقيقة","فورًا","يدعم / يساند"]},{"type":"gap_fill","prompt":"_____, they shouldn't hide them.","answer":"in fact"},{"type":"meaning_mcq","prompt":"in fact","answer":"في الحقيقة","distractors":["يثق / ثقة","موقف / وضع","سرّ"]},{"type":"gap_fill","prompt":"It was only _____, so don't worry.","answer":"natural"},{"type":"meaning_mcq","prompt":"natural","answer":"طبيعي","distractors":["سرّ","خطير","تمامًا"]},{"type":"gap_fill","prompt":"I was really _____.","answer":"scared"},{"type":"meaning_mcq","prompt":"scared","answer":"خائف","distractors":["طبيعي","يدعم / يساند","شخص بالغ"]},{"type":"gap_fill","prompt":"You were trying to _____ me.","answer":"support"},{"type":"meaning_mcq","prompt":"support","answer":"يدعم / يساند","distractors":["في الحقيقة","شخص بالغ","في البداية"]},{"type":"gap_fill","prompt":"Tina was _____ about Tim.","answer":"worried"},{"type":"meaning_mcq","prompt":"worried","answer":"قلق","distractors":["خطر","خائف","في البداية"]},{"type":"gap_fill","prompt":"You should tell an _____ immediately.","answer":"adult"},{"type":"meaning_mcq","prompt":"adult","answer":"شخص بالغ","distractors":["قلق","يثق / ثقة","يدعم / يساند"]},{"type":"gap_fill","prompt":"_____, he may be angry.","answer":"at first"},{"type":"meaning_mcq","prompt":"at first","answer":"في البداية","distractors":["يدعم / يساند","خطر","خطير"]},{"type":"gap_fill","prompt":"We can trust each other _____.","answer":"completely"},{"type":"meaning_mcq","prompt":"completely","answer":"تمامًا","distractors":["طبيعي","شخص بالغ","محرَج"]},{"type":"gap_fill","prompt":"Perhaps he'll understand the _____.","answer":"danger"},{"type":"meaning_mcq","prompt":"danger","answer":"خطر","distractors":["سرّ","تمامًا","في البداية"]},{"type":"gap_fill","prompt":"He's planning to do something _____.","answer":"dangerous"},{"type":"meaning_mcq","prompt":"dangerous","answer":"خطير","distractors":["طبيعي","قلق","خطر"]},{"type":"gap_fill","prompt":"_____ you talk, he'll understand.","answer":"if"},{"type":"meaning_mcq","prompt":"if","answer":"إذا","distractors":["خطير","وحيد / بمفرده","سرّ"]},{"type":"gap_fill","prompt":"Tell an adult _____.","answer":"immediately"},{"type":"meaning_mcq","prompt":"immediately","answer":"فورًا","distractors":["تمامًا","خطير","خائف"]},{"type":"gap_fill","prompt":"We tell each other all our _____s.","answer":"secret"},{"type":"meaning_mcq","prompt":"secret","answer":"سرّ","distractors":["في البداية","في الحقيقة","محرَج"]},{"type":"gap_fill","prompt":"I've been in the same _____.","answer":"situation"},{"type":"meaning_mcq","prompt":"situation","answer":"موقف / وضع","distractors":["خطير","فورًا","يدعم / يساند"]},{"type":"gap_fill","prompt":"You can never break his _____.","answer":"trust"},{"type":"meaning_mcq","prompt":"trust","answer":"يثق / ثقة","distractors":["وحيد / بمفرده","سرّ","خائف"]},{"type":"grammar_reorder","grammar":"When / If + المضارع البسيط، + المضارع البسيط أو الأفعال الناقصة","answer":"When people are friends, they don't have to hide their feelings.","tokens":["friends,","hide","their","to","When","feelings","have","they","people","don't","are"]},{"type":"grammar_reorder","grammar":"When / If + المضارع البسيط، + المضارع البسيط أو الأفعال الناقصة","answer":"I always want to help when a friend is upset.","tokens":["friend","always","when","to","is","upset","help","I","a","want"]},{"type":"grammar_reorder","grammar":"الجملة الشرطية من النوع الأوّل","answer":"If I do that, I'll lose my best friend.","tokens":["do","If","friend","I","that,","lose","I'll","best","my"]},{"type":"grammar_reorder","grammar":"الجملة الشرطية من النوع الأوّل","answer":"If you talk, perhaps he'll understand the danger better.","tokens":["better","If","danger","the","perhaps","he'll","understand","you","talk,"]},{"type":"dialogue_order","lines":["Hi, Tina. What's the news from the hospital? How's Tim?","He was much better when we visited him last night.","Great! And you look happier now. You were very upset yesterday morning.","Yes, I was really scared.","Well, it's fantastic that you don't need to worry now.","Listen, Nadia, I want to say sorry for yesterday."]}],"verified":true,"notes":"Vocabulary words, dialogues and grammar points verified against the PDF; Arabic meanings/explanations authored; examples drawn or adapted from the unit text."},{"number":7,"semester":1,"title":"Revision 1","page":76,"pages":[76,81],"revision":true,"vocabulary":[],"sentences":["Hello, Nadia. It's Tina.","Hi! It's good to hear you. Haven't you been away for a week?","That's right. We've been staying with our cousins in the north. We used to live near them, and we always come back to visit them in the spring holidays.","And what have you been doing?","Oh, lots of things."],"dialogues":[{"title":"Revision dialogue: Tina calls Nadia","page":76,"source":"verbatim from Pupil's Book","lines":[{"speaker":"Tina","gender":"f","gender_verified":true,"text":"Hello, Nadia. It's Tina."},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Hi! It's good to hear you. Haven't you been away for a week?"},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"That's right. We've been staying with our cousins in the north. We used to live near them, and we always come back to visit them in the spring holidays."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"And what have you been doing?"},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Oh, lots of things."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"I called yesterday, but you didn't answer."},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Sorry. We were at the cinema."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"What did you see?"},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"The new Spiderman film. I was quite scared sometimes!"},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Guess what! I left my coat in the cinema."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"Really?"},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Yes, we ran back and looked everywhere, but we couldn't find it."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"That's terrible!"},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Yes, I was very upset, but everything was fine in the end. You see, the cinema people had it. They saw it was mine and gave it back."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"We'll be home on Wednesday."},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Great! I can't wait."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"I can't, either. And listen, my birthday party is on Saturday. Can you come?"},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"I'd better ask, but I think it'll be OK."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"Good, and if it's sunny, we could go to the park first."},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Well, OK, but it won't be very warm. I'm pleased I got my coat back!"}]}],"texts":[],"grammar":[],"grammar_en":["Revision of Units 1–6"],"pronunciation":[],"functions":["revision of Units 1–6"],"writing":[],"task":"","seeds":[],"verified":false,"notes":"Revision unit: no new word box in the book (vocabulary=[]); dialogue verbatim from p76; exercises in book_exercises."},{"number":8,"semester":2,"title":"Different people, different clothes","page":4,"pages":[4,15],"revision":false,"vocabulary":[{"word":"assistant","arabic":"مساعد / بائع في متجر","example":"Let's ask the assistant.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"centimetre (cm)","arabic":"سنتيمتر","example":"I'm 165 centimetres.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"crazy about","arabic":"مولع بـ","example":"Ahmad is crazy about basketball.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"dollar","arabic":"دولار","example":"They're ninety-nine dollars ninety-nine.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"grade","arabic":"صفّ دراسي","example":"He's the best player in Grade 6.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"just (= exactly)","arabic":"تمامًا","example":"These are just right.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"smart","arabic":"أنيق","example":"These red trainers look smart.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"size","arabic":"مقاس / حجم","example":"We need them in a larger size.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"sports shop","arabic":"متجر أدوات رياضية","example":"Let's go into this sports shop.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"coat","arabic":"معطف","example":"I wear a coat in winter.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"comfortably","arabic":"بشكل مريح","example":"We can dress more comfortably in summer.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"during","arabic":"خلال","example":"During our long winters, we wear warm sweaters.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"gloves","arabic":"قفّازات","example":"We wear thick gloves at work.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"hard hat","arabic":"خوذة واقية","example":"Workers wear hard hats.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"safety","arabic":"سلامة","example":"We wear safety boots.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"tidy","arabic":"مرتّب","example":"We try hard to be smart and tidy.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"untidy","arabic":"غير مرتّب","example":"His room is untidy.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"comfortable","arabic":"مريح","example":"These shoes are comfortable.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"uncomfortable","arabic":"غير مريح","example":"They're uncomfortable, but they're safe.","source":"book word box","example_note":"example adapted from the unit text"}],"sentences":["These are just right.","How much are they, please?","They're ninety-nine dollars ninety-nine.","He's almost as tall as me already.","Better safe than sorry."],"dialogues":[{"title":"Period 1 conversation","page":4,"source":"verbatim from Pupil's Book","lines":[{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"Omar, what would Ahmad like?"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"A T-shirt perhaps."},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"No, let's find something better than that. Something more exciting."},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"Ahmad is crazy about basketball, isn't he?"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Yes, everyone says he's the best player in Grade 6."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"So what about some trainers?"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"He'd love that! He's growing fast, and his old ones are getting small."},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"Let's go into this sports shop."},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"Look, here are the trainers."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"These red ones look smart."},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"But they don't seem as strong as these green ones."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Yes, they're great, but they're only size 32 and Ahmad is almost a 36."},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"Are his feet really as big as that? He's going to be very tall!"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"You're right. I'm 165 centimetres, and he's almost as tall as me already."},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"Let's ask the assistant … Excuse me."},{"speaker":"Assistant","gender":"m","gender_verified":false,"text":"How can I help you?"},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"These are nice, but we need them in a larger size. Size 36."},{"speaker":"Assistant","gender":"m","gender_verified":false,"text":"Here you are."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Ah, yes, these are just right."},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"Good. How much are they, please?"},{"speaker":"Assistant","gender":"m","gender_verified":false,"text":"They're ninety-nine dollars ninety-nine."},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"Good. We'll take them."}],"note":"Book has more than two speakers; 'speaker' gives the character. Map to A/B voices by speaker+gender."}],"texts":[{"title":"Clothes for work and weather","page":8,"paragraphs":["Deema, from Palestine, is a police officer. She wears her uniform proudly. She tries to be smart and tidy because people trust the police more.","Bill, from Canada, wears warm sweaters and thick jackets in the long, dark winters. In the short summer, he dresses more comfortably in T-shirts and shorts.","Maria, from Mexico, is dressing as nicely as she can for a big family party.","Abdullah, from Kuwait, wears a hard hat, safety boots and thick gloves at work. They are uncomfortable, but they are better than an accident. 'Better safe than sorry,' he says."],"source":"adapted (shortened) from the Pupil's Book reading text"}],"grammar":[{"title":"مقارنة الصفات","explanation":"للصفات القصيرة نضيف er للمقارنة وest للتفضيل (with the)، وللصفات الطويلة نستعمل more / the most. وللمساواة: as + صفة + as، وللنفي: not as … as.","examples":["Let's find something better than that.","Something more exciting.","He's the best player in Grade 6.","They don't seem as strong as these green ones."]},{"title":"مقارنة الظروف","explanation":"تُقارن الظروف المنتهية بـ ly باستعمال more، أمّا الظروف الشاذّة: hard → harder، fast → faster، well → better.","examples":["We dress as smartly and tidily as we can.","Today, we do things more carefully than we did then.","We protect ourselves as well as we can."]}],"grammar_en":["Comparison of adjectives: -er / -est and more / most","as … as","Comparison of adverbs, including irregulars hard / fast / well"],"pronunciation":[{"title":"numbers (tens and teens)","words":[]}],"functions":["making comparisons","buying and selling","preparing a ‘Lost’ public announcement"],"writing":["writing quick notes; writing a public announcement"],"task":"Preparing a 'Lost' public announcement","seeds":[{"type":"gap_fill","prompt":"Let's ask the _____.","answer":"assistant"},{"type":"meaning_mcq","prompt":"assistant","answer":"مساعد / بائع في متجر","distractors":["مرتّب","مريح","غير مرتّب"]},{"type":"gap_fill","prompt":"I'm 165 _____s.","answer":"centimetre"},{"type":"meaning_mcq","prompt":"centimetre (cm)","answer":"سنتيمتر","distractors":["أنيق","صفّ دراسي","غير مريح"]},{"type":"gap_fill","prompt":"Ahmad is _____ basketball.","answer":"crazy about"},{"type":"meaning_mcq","prompt":"crazy about","answer":"مولع بـ","distractors":["خلال","بشكل مريح","خوذة واقية"]},{"type":"gap_fill","prompt":"They're ninety-nine _____s ninety-nine.","answer":"dollar"},{"type":"meaning_mcq","prompt":"dollar","answer":"دولار","distractors":["صفّ دراسي","مرتّب","أنيق"]},{"type":"gap_fill","prompt":"He's the best player in _____ 6.","answer":"grade"},{"type":"meaning_mcq","prompt":"grade","answer":"صفّ دراسي","distractors":["بشكل مريح","أنيق","قفّازات"]},{"type":"gap_fill","prompt":"These are _____ right.","answer":"just"},{"type":"meaning_mcq","prompt":"just (= exactly)","answer":"تمامًا","distractors":["قفّازات","مريح","سنتيمتر"]},{"type":"gap_fill","prompt":"These red trainers look _____.","answer":"smart"},{"type":"meaning_mcq","prompt":"smart","answer":"أنيق","distractors":["خوذة واقية","معطف","مولع بـ"]},{"type":"gap_fill","prompt":"We need them in a larger _____.","answer":"size"},{"type":"meaning_mcq","prompt":"size","answer":"مقاس / حجم","distractors":["متجر أدوات رياضية","غير مرتّب","مرتّب"]},{"type":"gap_fill","prompt":"Let's go into this _____.","answer":"sports shop"},{"type":"meaning_mcq","prompt":"sports shop","answer":"متجر أدوات رياضية","distractors":["بشكل مريح","أنيق","غير مرتّب"]},{"type":"gap_fill","prompt":"I wear a _____ in winter.","answer":"coat"},{"type":"meaning_mcq","prompt":"coat","answer":"معطف","distractors":["غير مريح","مولع بـ","مريح"]},{"type":"gap_fill","prompt":"We can dress more _____ in summer.","answer":"comfortably"},{"type":"meaning_mcq","prompt":"comfortably","answer":"بشكل مريح","distractors":["معطف","مولع بـ","تمامًا"]},{"type":"gap_fill","prompt":"_____ our long winters, we wear warm sweaters.","answer":"during"},{"type":"meaning_mcq","prompt":"during","answer":"خلال","distractors":["خوذة واقية","دولار","مريح"]},{"type":"gap_fill","prompt":"We wear thick _____ at work.","answer":"gloves"},{"type":"meaning_mcq","prompt":"gloves","answer":"قفّازات","distractors":["تمامًا","غير مريح","غير مرتّب"]},{"type":"gap_fill","prompt":"Workers wear _____s.","answer":"hard hat"},{"type":"meaning_mcq","prompt":"hard hat","answer":"خوذة واقية","distractors":["بشكل مريح","مقاس / حجم","أنيق"]},{"type":"gap_fill","prompt":"We wear _____ boots.","answer":"safety"},{"type":"meaning_mcq","prompt":"safety","answer":"سلامة","distractors":["مرتّب","مقاس / حجم","قفّازات"]},{"type":"gap_fill","prompt":"We try hard to be smart and _____.","answer":"tidy"},{"type":"meaning_mcq","prompt":"tidy","answer":"مرتّب","distractors":["مساعد / بائع في متجر","مريح","خلال"]},{"type":"gap_fill","prompt":"His room is _____.","answer":"untidy"},{"type":"meaning_mcq","prompt":"untidy","answer":"غير مرتّب","distractors":["معطف","دولار","مرتّب"]},{"type":"gap_fill","prompt":"These shoes are _____.","answer":"comfortable"},{"type":"meaning_mcq","prompt":"comfortable","answer":"مريح","distractors":["سنتيمتر","دولار","سلامة"]},{"type":"gap_fill","prompt":"They're _____, but they're safe.","answer":"uncomfortable"},{"type":"meaning_mcq","prompt":"uncomfortable","answer":"غير مريح","distractors":["خلال","متجر أدوات رياضية","بشكل مريح"]},{"type":"grammar_reorder","grammar":"مقارنة الصفات","answer":"Let's find something better than that.","tokens":["find","better","than","that","something","Let's"]},{"type":"grammar_reorder","grammar":"مقارنة الصفات","answer":"Something more exciting.","tokens":["Something","more","exciting"]},{"type":"grammar_reorder","grammar":"مقارنة الظروف","answer":"We dress as smartly and tidily as we can.","tokens":["and","tidily","smartly","we","dress","can","We","as","as"]},{"type":"grammar_reorder","grammar":"مقارنة الظروف","answer":"Today, we do things more carefully than we did then.","tokens":["things","did","do","then","more","we","Today,","than","carefully","we"]},{"type":"dialogue_order","lines":["Omar, what would Ahmad like?","A T-shirt perhaps.","No, let's find something better than that. Something more exciting.","Ahmad is crazy about basketball, isn't he?","Yes, everyone says he's the best player in Grade 6.","So what about some trainers?"]}],"verified":true,"notes":"Vocabulary words, dialogues and grammar points verified against the PDF; Arabic meanings/explanations authored; examples drawn or adapted from the unit text."},{"number":9,"semester":2,"title":"The world of food","page":16,"pages":[16,27],"revision":false,"vocabulary":[{"word":"can","arabic":"علبة معدنية","example":"Get a large can of olive oil.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"carton","arabic":"علبة كرتونية","example":"Get a large carton of tomato paste.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"each","arabic":"لكلٍّ / كلّ واحد","example":"Buy yourselves an ice cream each.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"ground meat","arabic":"لحم مفروم","example":"We don't have any ground meat.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"jar","arabic":"مرطبان","example":"Get a small jar of olives.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"list","arabic":"قائمة","example":"I'll make a list.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"litre","arabic":"لتر","example":"Get a two-litre can.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"regular","arabic":"عادي (الحجم)","example":"Just the regular size, please.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"tomato paste","arabic":"معجون الطماطم","example":"Is there any tomato paste?","source":"book word box","example_note":"example adapted from the unit text"},{"word":"tub","arabic":"علبة (بلاستيكية)","example":"One regular tub of ice cream.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"climate","arabic":"مناخ","example":"Palestine's climate is just right for olives.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"export","arabic":"يصدّر","example":"We export a lot of olive oil.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"import","arabic":"يستورد","example":"We do not import tea from Japan.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"probably","arabic":"على الأرجح","example":"The wheat was probably American.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"produce","arabic":"يُنتج","example":"Palestine produces a lot of olives.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"quality","arabic":"جودة","example":"The quality is excellent.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"quantity","arabic":"كمّية","example":"The USA grows huge quantities of wheat.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"pasta","arabic":"معكرونة","example":"Pasta is made from wheat.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"wheat","arabic":"قمح","example":"We use wheat to make bread.","source":"book word box","example_note":"example adapted from the unit text"}],"sentences":["Could you do some shopping for me?","How much should we get?","Are there any olives?","There are some, but not many.","Oh, and one more thing …"],"dialogues":[{"title":"Period 1 conversation","page":16,"source":"verbatim from Pupil's Book","lines":[{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"Could you do some shopping for me?"},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"Fine. I'll make a list."},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"Right. I want to make some kebabs, but we don't have any ground meat."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"How much should we get?"},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"A kilo, please."},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"Ground meat … one kilo."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"There aren't any tomatoes either. How many should we get?"},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"About two kilos."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"And is there any tomato paste?"},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"No, there isn't. So get a large carton."},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"Tomatoes … two kilos … Tomato paste … a large carton."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"Are there any olives?"},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"There are some, but not many."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"How many would you like?"},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"Get a small jar."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"And there isn't much olive oil."},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"So please get a large can – two litres."},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"Olives … one small jar … Olive oil … one two-litre can."},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"And let's get some ice cream for everyone."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"Oh, good! But how much? A large tub?"},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"No, just the regular size, please."},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"Right. Ice cream … one regular tub."},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"Oh, and one more thing … Buy yourselves an ice cream each."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"Thanks!"}],"note":"Book has more than two speakers; 'speaker' gives the character. Map to A/B voices by speaker+gender."}],"texts":[{"title":"The food and drink quiz","page":20,"paragraphs":["A lot of our tea comes from India. Brazil grows coffee, not tea, and tea from Japan is green, not black.","Canada and Russia grow a lot of wheat, but the USA grows and exports huge quantities. The bread you ate this morning was probably made with American wheat.","China does not grow olives, and Kuwait's desert climate is bad for olive trees. But Palestine's climate is just right. We produce and export a lot of olives and olive oil, and the quality is excellent."],"source":"adapted (shortened) from the Pupil's Book reading text"}],"grammar":[{"title":"some و any","explanation":"تُستعمل some في الجمل المثبتة وفي العروض والطلبات، وany في النفي والسؤال، مع الأسماء المعدودة الجمع وغير المعدودة.","examples":["We don't have any ground meat.","Are there any olives?","There are some, but not many."]},{"title":"How much / How many","explanation":"How many مع الأسماء المعدودة الجمع، وHow much مع الأسماء غير المعدودة وللسؤال عن السعر. وكذلك many / much.","examples":["How many should we get?","How much should we get?","There isn't much olive oil."]},{"title":"أدوات التعريف والتنكير والاستعمال العامّ","explanation":"نستعمل a/an مع المفرد المعدود غير المحدّد، وthe مع الشيء المعروف أو المحدّد، ولا نستعمل أداةً عند الحديث عن الأشياء بشكلٍ عامّ.","examples":["Get a small jar.","The wheat was probably American.","We use wheat to make bread."]}],"grammar_en":["some / any","(How) much / many","indefinite / definite & generic forms (a / an / the / zero article)"],"pronunciation":[{"title":"rhyme","words":[]}],"functions":["talking about quantities","planning a class picnic"],"writing":["topic sentences"],"task":"Planning a class picnic","seeds":[{"type":"gap_fill","prompt":"Get a large _____ of olive oil.","answer":"can"},{"type":"meaning_mcq","prompt":"can","answer":"علبة معدنية","distractors":["يصدّر","يستورد","لحم مفروم"]},{"type":"gap_fill","prompt":"Get a large _____ of tomato paste.","answer":"carton"},{"type":"meaning_mcq","prompt":"carton","answer":"علبة كرتونية","distractors":["لتر","معكرونة","يصدّر"]},{"type":"gap_fill","prompt":"Buy yourselves an ice cream _____.","answer":"each"},{"type":"meaning_mcq","prompt":"each","answer":"لكلٍّ / كلّ واحد","distractors":["قمح","يُنتج","مناخ"]},{"type":"gap_fill","prompt":"We don't have any _____.","answer":"ground meat"},{"type":"meaning_mcq","prompt":"ground meat","answer":"لحم مفروم","distractors":["قائمة","معجون الطماطم","على الأرجح"]},{"type":"gap_fill","prompt":"Get a small _____ of olives.","answer":"jar"},{"type":"meaning_mcq","prompt":"jar","answer":"مرطبان","distractors":["علبة معدنية","لحم مفروم","قائمة"]},{"type":"gap_fill","prompt":"I'll make a _____.","answer":"list"},{"type":"meaning_mcq","prompt":"list","answer":"قائمة","distractors":["معجون الطماطم","لكلٍّ / كلّ واحد","لتر"]},{"type":"gap_fill","prompt":"Get a two-_____ can.","answer":"litre"},{"type":"meaning_mcq","prompt":"litre","answer":"لتر","distractors":["مرطبان","كمّية","مناخ"]},{"type":"gap_fill","prompt":"Just the _____ size, please.","answer":"regular"},{"type":"meaning_mcq","prompt":"regular","answer":"عادي (الحجم)","distractors":["قمح","على الأرجح","لكلٍّ / كلّ واحد"]},{"type":"gap_fill","prompt":"Is there any _____?","answer":"tomato paste"},{"type":"meaning_mcq","prompt":"tomato paste","answer":"معجون الطماطم","distractors":["جودة","مناخ","لكلٍّ / كلّ واحد"]},{"type":"gap_fill","prompt":"One regular _____ of ice cream.","answer":"tub"},{"type":"meaning_mcq","prompt":"tub","answer":"علبة (بلاستيكية)","distractors":["على الأرجح","جودة","كمّية"]},{"type":"gap_fill","prompt":"Palestine's _____ is just right for olives.","answer":"climate"},{"type":"meaning_mcq","prompt":"climate","answer":"مناخ","distractors":["يُنتج","يصدّر","كمّية"]},{"type":"gap_fill","prompt":"We _____ a lot of olive oil.","answer":"export"},{"type":"meaning_mcq","prompt":"export","answer":"يصدّر","distractors":["عادي (الحجم)","علبة (بلاستيكية)","علبة كرتونية"]},{"type":"gap_fill","prompt":"We do not _____ tea from Japan.","answer":"import"},{"type":"meaning_mcq","prompt":"import","answer":"يستورد","distractors":["لحم مفروم","علبة معدنية","يصدّر"]},{"type":"gap_fill","prompt":"The wheat was _____ American.","answer":"probably"},{"type":"meaning_mcq","prompt":"probably","answer":"على الأرجح","distractors":["يُنتج","علبة معدنية","معجون الطماطم"]},{"type":"gap_fill","prompt":"Palestine _____s a lot of olives.","answer":"produce"},{"type":"meaning_mcq","prompt":"produce","answer":"يُنتج","distractors":["يصدّر","علبة كرتونية","قائمة"]},{"type":"gap_fill","prompt":"The _____ is excellent.","answer":"quality"},{"type":"meaning_mcq","prompt":"quality","answer":"جودة","distractors":["لكلٍّ / كلّ واحد","كمّية","علبة كرتونية"]},{"type":"meaning_mcq","prompt":"quantity","answer":"كمّية","distractors":["معكرونة","علبة معدنية","علبة كرتونية"]},{"type":"gap_fill","prompt":"_____ is made from wheat.","answer":"pasta"},{"type":"meaning_mcq","prompt":"pasta","answer":"معكرونة","distractors":["لحم مفروم","مناخ","مرطبان"]},{"type":"gap_fill","prompt":"We use _____ to make bread.","answer":"wheat"},{"type":"meaning_mcq","prompt":"wheat","answer":"قمح","distractors":["عادي (الحجم)","يصدّر","كمّية"]},{"type":"grammar_reorder","grammar":"some و any","answer":"We don't have any ground meat.","tokens":["any","have","don't","We","meat","ground"]},{"type":"grammar_reorder","grammar":"some و any","answer":"Are there any olives?","tokens":["any","there","olives","Are"]},{"type":"grammar_reorder","grammar":"How much / How many","answer":"How many should we get?","tokens":["should","get","many","we","How"]},{"type":"grammar_reorder","grammar":"How much / How many","answer":"How much should we get?","tokens":["How","get","we","should","much"]},{"type":"grammar_reorder","grammar":"أدوات التعريف والتنكير والاستعمال العامّ","answer":"Get a small jar.","tokens":["a","small","Get","jar"]},{"type":"grammar_reorder","grammar":"أدوات التعريف والتنكير والاستعمال العامّ","answer":"The wheat was probably American.","tokens":["American","probably","was","The","wheat"]},{"type":"dialogue_order","lines":["Could you do some shopping for me?","Fine. I'll make a list.","Right. I want to make some kebabs, but we don't have any ground meat.","How much should we get?","A kilo, please.","Ground meat … one kilo."]}],"verified":true,"notes":"Vocabulary words, dialogues and grammar points verified against the PDF; Arabic meanings/explanations authored; examples drawn or adapted from the unit text."},{"number":10,"semester":2,"title":"Back home in Palestine","page":28,"pages":[28,39],"revision":false,"vocabulary":[{"word":"backpack","arabic":"حقيبة ظهر","example":"Who's the boy with a backpack?","source":"book word box","example_note":"example adapted from the unit text"},{"word":"beard","arabic":"لحية","example":"He has glasses and a beard.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"centre","arabic":"وسط / مركز","example":"She's the one in the centre.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"curly","arabic":"مجعّد","example":"Sameer has short, curly hair.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"glasses","arabic":"نظّارة","example":"The brother with glasses looks young.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"moustache","arabic":"شارب","example":"You mean the one with a moustache.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"side","arabic":"جانب / طرف (من العائلة)","example":"It's a picnic with my mum's side of the family.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"straight","arabic":"ناعم / مستقيم (الشعر)","example":"Ali has long, straight hair.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"wife","arabic":"زوجة","example":"His wife, Aunt Rania, is next to him.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"area","arabic":"منطقة","example":"Human beings first visited the area 12,000 years ago.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"construct","arabic":"يبني / يشيّد","example":"They constructed the first city in the world.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"crop","arabic":"محصول","example":"They grow bananas and other crops.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"deep","arabic":"عميق","example":"Jericho stands in a deep valley.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"hotel","arabic":"فندق","example":"There are hotels for visitors.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"human being","arabic":"إنسان","example":"Human beings first visited the area long ago.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"tower","arabic":"برج","example":"Later, it had a high tower.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"various","arabic":"متنوّع","example":"They grow various fruit and vegetables.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"tourism","arabic":"سياحة","example":"A lot of people work in tourism.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"tourist","arabic":"سائح","example":"Tourists love seeing the walls.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"including","arabic":"بما في ذلك","example":"various crops, including dates","source":"book word box","example_note":"example adapted from the unit text"}],"sentences":["Oh, let's have a look!","She's the one in the centre.","Who's the one with long, straight hair?","He's the one behind the camera!","Jericho is a small city which stands in a deep valley."],"dialogues":[{"title":"Period 1 conversation","page":28,"source":"verbatim from Pupil's Book","lines":[{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Look. My brother Ahmad has emailed me a family photo."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"Oh, let's have a look!"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"It's a picnic with my mum's side of the family. They're at a beautiful place near Jericho."},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"Ah! She's the one in the centre, and your dad's standing behind her."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"That's right."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"Are those her brothers next to her? They look like brothers and sister."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Yes, the one on the left is her older brother, our Uncle Nazmi."},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"You mean the one with a moustache."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Right, and his wife, Aunt Rania, is the one next to him in a red jacket."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"And the brother with glasses and a beard? He looks quite young."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Yes, Uncle Ameer is the youngest of the three. And his wife, Aunt Deema, is the one in a green dress. They haven't got any children yet."},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"So are the children all Uncle Nazmi's?"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"That's right. Ali, Hazem and Sameer."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"Who's the one with long, straight hair?"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"That's Ali, and he's the oldest. He's finished school."},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"And who's the boy with a backpack?"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"That's Hazem. Then there's Sameer with short, curly hair."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"But where's your brother Ahmad with the big feet?"},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"He's the one behind the camera!"}],"note":"Book has more than two speakers; 'speaker' gives the character. Map to A/B voices by speaker+gender."}],"texts":[{"title":"Jericho – The City of Palm Trees","page":32,"paragraphs":["Jericho is a small city in a deep valley between Jerusalem and Amman, near the Dead Sea. The Dead Sea is the lowest place on Earth.","Jericho is popular with tourists in the warm winter months, and many people work in tourism. Farming is also important. Farmers grow bananas, dates and various other crops.","Human beings first started visiting the area 12,000 years ago. They became some of the world's first farmers and constructed the first city in the world. Tourists love seeing its ancient walls today."],"source":"adapted (shortened) from the Pupil's Book reading text"}],"grammar":[{"title":"تحديد الأشخاص: the one with / in","explanation":"نحدّد الشخص بقول (the one + with + صفة جسدية أو شيء) أو (the one + in + لباس) أو بموقعه (on the left / in the centre).","examples":["She's the one in the centre.","The one on the left is her older brother.","Who's the one with long, straight hair?","Aunt Rania is the one next to him in a red jacket."]},{"title":"جمل الصلة المحدِّدة: who / which / that","explanation":"تُستعمل who للأشخاص، وwhich للأشياء، وthat لكليهما، لربط جملتين وتحديد الاسم المقصود.","examples":["Jericho is a small city which stands in a deep valley.","There were many people who chose to remain.","These were also the people that constructed the first city in the world."]}],"grammar_en":["It’s the house on the corner. Which is John? He’s the one with dark hair / in a green jacket.","Defining relative clauses with who, which and that as subject relatives"],"pronunciation":[{"title":"th /ð/ and th /θ/","words":[]}],"functions":["identifying people and things","describing a photo of friends"],"writing":["using pronouns instead of nouns"],"task":"Describing a photo of friends","seeds":[{"type":"gap_fill","prompt":"Who's the boy with a _____?","answer":"backpack"},{"type":"meaning_mcq","prompt":"backpack","answer":"حقيبة ظهر","distractors":["منطقة","لحية","سياحة"]},{"type":"gap_fill","prompt":"He has glasses and a _____.","answer":"beard"},{"type":"meaning_mcq","prompt":"beard","answer":"لحية","distractors":["وسط / مركز","يبني / يشيّد","شارب"]},{"type":"gap_fill","prompt":"She's the one in the _____.","answer":"centre"},{"type":"meaning_mcq","prompt":"centre","answer":"وسط / مركز","distractors":["يبني / يشيّد","سائح","ناعم / مستقيم (الشعر)"]},{"type":"gap_fill","prompt":"Sameer has short, _____ hair.","answer":"curly"},{"type":"meaning_mcq","prompt":"curly","answer":"مجعّد","distractors":["حقيبة ظهر","شارب","لحية"]},{"type":"gap_fill","prompt":"The brother with _____ looks young.","answer":"glasses"},{"type":"meaning_mcq","prompt":"glasses","answer":"نظّارة","distractors":["سياحة","شارب","عميق"]},{"type":"gap_fill","prompt":"You mean the one with a _____.","answer":"moustache"},{"type":"meaning_mcq","prompt":"moustache","answer":"شارب","distractors":["منطقة","برج","بما في ذلك"]},{"type":"gap_fill","prompt":"It's a picnic with my mum's _____ of the family.","answer":"side"},{"type":"meaning_mcq","prompt":"side","answer":"جانب / طرف (من العائلة)","distractors":["عميق","يبني / يشيّد","نظّارة"]},{"type":"gap_fill","prompt":"Ali has long, _____ hair.","answer":"straight"},{"type":"meaning_mcq","prompt":"straight","answer":"ناعم / مستقيم (الشعر)","distractors":["عميق","برج","سائح"]},{"type":"gap_fill","prompt":"His _____, Aunt Rania, is next to him.","answer":"wife"},{"type":"meaning_mcq","prompt":"wife","answer":"زوجة","distractors":["ناعم / مستقيم (الشعر)","سياحة","محصول"]},{"type":"gap_fill","prompt":"Human beings first visited the _____ 12,000 years ago.","answer":"area"},{"type":"meaning_mcq","prompt":"area","answer":"منطقة","distractors":["وسط / مركز","سائح","زوجة"]},{"type":"gap_fill","prompt":"They _____ed the first city in the world.","answer":"construct"},{"type":"meaning_mcq","prompt":"construct","answer":"يبني / يشيّد","distractors":["بما في ذلك","حقيبة ظهر","منطقة"]},{"type":"gap_fill","prompt":"They grow bananas and other _____s.","answer":"crop"},{"type":"meaning_mcq","prompt":"crop","answer":"محصول","distractors":["يبني / يشيّد","سياحة","مجعّد"]},{"type":"gap_fill","prompt":"Jericho stands in a _____ valley.","answer":"deep"},{"type":"meaning_mcq","prompt":"deep","answer":"عميق","distractors":["زوجة","حقيبة ظهر","سائح"]},{"type":"gap_fill","prompt":"There are _____s for visitors.","answer":"hotel"},{"type":"meaning_mcq","prompt":"hotel","answer":"فندق","distractors":["بما في ذلك","برج","عميق"]},{"type":"gap_fill","prompt":"_____s first visited the area long ago.","answer":"human being"},{"type":"meaning_mcq","prompt":"human being","answer":"إنسان","distractors":["بما في ذلك","سياحة","جانب / طرف (من العائلة)"]},{"type":"gap_fill","prompt":"Later, it had a high _____.","answer":"tower"},{"type":"meaning_mcq","prompt":"tower","answer":"برج","distractors":["حقيبة ظهر","بما في ذلك","نظّارة"]},{"type":"gap_fill","prompt":"They grow _____ fruit and vegetables.","answer":"various"},{"type":"meaning_mcq","prompt":"various","answer":"متنوّع","distractors":["سائح","لحية","يبني / يشيّد"]},{"type":"gap_fill","prompt":"A lot of people work in _____.","answer":"tourism"},{"type":"meaning_mcq","prompt":"tourism","answer":"سياحة","distractors":["يبني / يشيّد","سائح","ناعم / مستقيم (الشعر)"]},{"type":"gap_fill","prompt":"_____s love seeing the walls.","answer":"tourist"},{"type":"meaning_mcq","prompt":"tourist","answer":"سائح","distractors":["عميق","سياحة","جانب / طرف (من العائلة)"]},{"type":"gap_fill","prompt":"various crops, _____ dates","answer":"including"},{"type":"meaning_mcq","prompt":"including","answer":"بما في ذلك","distractors":["برج","إنسان","منطقة"]},{"type":"grammar_reorder","grammar":"تحديد الأشخاص: the one with / in","answer":"She's the one in the centre.","tokens":["She's","the","one","centre","in","the"]},{"type":"grammar_reorder","grammar":"تحديد الأشخاص: the one with / in","answer":"The one on the left is her older brother.","tokens":["older","the","on","brother","is","her","The","left","one"]},{"type":"grammar_reorder","grammar":"جمل الصلة المحدِّدة: who / which / that","answer":"Jericho is a small city which stands in a deep valley.","tokens":["deep","city","a","small","stands","valley","which","in","is","a","Jericho"]},{"type":"grammar_reorder","grammar":"جمل الصلة المحدِّدة: who / which / that","answer":"There were many people who chose to remain.","tokens":["remain","chose","people","There","who","were","to","many"]},{"type":"dialogue_order","lines":["Look. My brother Ahmad has emailed me a family photo.","Oh, let's have a look!","It's a picnic with my mum's side of the family. They're at a beautiful place near Jericho.","Ah! She's the one in the centre, and your dad's standing behind her.","That's right.","Are those her brothers next to her? They look like brothers and sister."]}],"verified":true,"notes":"Vocabulary words, dialogues and grammar points verified against the PDF; Arabic meanings/explanations authored; examples drawn or adapted from the unit text."},{"number":11,"semester":2,"title":"A Palestinian wedding","page":40,"pages":[40,51],"revision":false,"vocabulary":[{"word":"all right","arabic":"حسنًا","example":"Well, all right.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"bride","arabic":"عروس","example":"The bride looks beautiful!","source":"book word box","example_note":"example adapted from the unit text"},{"word":"congratulations","arabic":"تهانينا","example":"He receives everyone's congratulations.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"DVD","arabic":"قرص فيديو رقمي","example":"Who'd like to watch the wedding DVD?","source":"book word box","example_note":"example adapted from the unit text"},{"word":"follow","arabic":"يتبع","example":"The bride's following in a car.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"full","arabic":"شبعان / ممتلئ","example":"No, thanks. I'm full!","source":"book word box","example_note":"example adapted from the unit text"},{"word":"groom","arabic":"عريس","example":"He's the groom.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"guest","arabic":"ضيف","example":"There are hundreds of guests!","source":"book word box","example_note":"example adapted from the unit text"},{"word":"as","arabic":"بما أنّ / كـ","example":"As it was late, we went home.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"celebrate","arabic":"يحتفل","example":"People celebrate weddings in many ways.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"custom","arabic":"عادة / تقليد","example":"Here are some interesting wedding customs.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"dough","arabic":"عجين","example":"The bride sticks bread dough to the door.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"hold","arabic":"يمسك","example":"They both hold the knife.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"purpose","arabic":"غرض / هدف","example":"They are all for the same purpose.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"ring","arabic":"خاتم","example":"He gives his bride her wedding ring.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"spirit","arabic":"روح","example":"They stop bad spirits from finding the bride.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"stick (v)","arabic":"يُلصق","example":"She sticks dough to the front door.","source":"book word box","example_note":"example adapted from the unit text"}],"sentences":["Would you like another cake?","No, thanks. I'm full!","Come on! Say yes!","Well, all right.","I'd prefer to watch the DVD again."],"dialogues":[{"title":"Period 1 conversation","page":40,"source":"verbatim from Pupil's Book","lines":[{"speaker":"Mrs Kamal","gender":"f","gender_verified":true,"text":"Would you like another cake?"},{"speaker":"Mike","gender":"m","gender_verified":true,"text":"Yes, please. I'd love another one!"},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"No, thanks, Mrs Kamal. I'm full!"},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"Who'd like to watch our cousin's wedding DVD? It's just arrived."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"I'd love to."},{"speaker":"Mike","gender":"m","gender_verified":true,"text":"Hm. I'd prefer to play computer games."},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"Come on, Mike! Say yes!"},{"speaker":"Mike","gender":"m","gender_verified":true,"text":"Well, all right."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"Is this the wedding party?"},{"speaker":"Mrs Kamal","gender":"f","gender_verified":true,"text":"No, it's Sahra. It's a party before the wedding day. The women are singing, and the men are dancing the traditional dabka."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"Everyone looks very happy!"},{"speaker":"Mike","gender":"m","gender_verified":true,"text":"What's happening now?"},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"We call this Zaffa. That's our cousin on the horse. He's the groom, and he's riding round town to receive everyone's congratulations."},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"The bride's following in a car. People are giving her their best wishes."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"She looks beautiful!"},{"speaker":"Mrs Kamal","gender":"f","gender_verified":true,"text":"This is the wedding party. Look, the bride and groom are sitting in the centre."},{"speaker":"Tina","gender":"f","gender_verified":true,"text":"There are hundreds of guests!"},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"Yes, everyone goes to a Palestinian wedding! We love them!"},{"speaker":"Nadia","gender":"f","gender_verified":true,"text":"It's so sad we couldn't go to this one."},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"And that's the end. So would you like to play computer games now, Mike?"},{"speaker":"Mike","gender":"m","gender_verified":true,"text":"Thanks, but I'd prefer to watch the DVD again. It was fantastic!"}],"note":"Book has more than two speakers; 'speaker' gives the character. Map to A/B voices by speaker+gender."}],"texts":[{"title":"What a wedding!","page":44,"paragraphs":["People celebrate weddings in a thousand different ways.","In the Philippines, the bride and her assistants all wear the same dresses to stop bad spirits from finding the bride.","In Spain, the groom gives his bride a ring and a little money to show that he will work hard for the family.","In many countries, the bride and groom hold the knife together to cut the cake. In Scotland, people keep half of the cake for when the first child arrives.","In Palestine, the bride sticks some bread dough to the front door of her new home. This shows that she and her husband will stay together all their lives."],"source":"adapted (shortened) from the Pupil's Book reading text"}],"grammar":[{"title":"العروض والردّ عليها","explanation":"نعرض بـ Would you like …? ونقبل بـ Yes, please / I'd love to، ونرفض بلطف بـ No, thanks، ونعبّر عن التفضيل بـ I'd prefer to + الفعل.","examples":["Would you like another cake?","Yes, please. I'd love another one!","No, thanks. I'm full!","I'd prefer to play computer games."]},{"title":"التعبير عن الغرض: to و in order to","explanation":"نعبّر عن الغرض أو السبب بـ (to + الفعل) أو (in order to + الفعل).","examples":["He's riding round town to receive everyone's congratulations.","He gives her a little money in order to show that he will work hard.","They both hold the knife in order to cut the cake together."]}],"grammar_en":["Offers and responses: Would you like …? I'd love / I'd prefer …","Purpose: to and in order to"],"pronunciation":[{"title":"silent letters","words":["know","write","listen","half"]}],"functions":["making and responding to offers","talking about purpose","preparing for a wedding"],"writing":["commas, apostrophes and full stops"],"task":"Preparing for a wedding","seeds":[{"type":"gap_fill","prompt":"Well, _____.","answer":"all right"},{"type":"meaning_mcq","prompt":"all right","answer":"حسنًا","distractors":["عريس","خاتم","يمسك"]},{"type":"gap_fill","prompt":"The _____ looks beautiful!","answer":"bride"},{"type":"meaning_mcq","prompt":"bride","answer":"عروس","distractors":["عريس","غرض / هدف","يتبع"]},{"type":"gap_fill","prompt":"He receives everyone's _____.","answer":"congratulations"},{"type":"meaning_mcq","prompt":"congratulations","answer":"تهانينا","distractors":["ضيف","خاتم","حسنًا"]},{"type":"gap_fill","prompt":"Who'd like to watch the wedding _____?","answer":"DVD"},{"type":"meaning_mcq","prompt":"DVD","answer":"قرص فيديو رقمي","distractors":["غرض / هدف","عادة / تقليد","يحتفل"]},{"type":"gap_fill","prompt":"The bride's _____ing in a car.","answer":"follow"},{"type":"meaning_mcq","prompt":"follow","answer":"يتبع","distractors":["بما أنّ / كـ","عادة / تقليد","عروس"]},{"type":"gap_fill","prompt":"No, thanks. I'm _____!","answer":"full"},{"type":"meaning_mcq","prompt":"full","answer":"شبعان / ممتلئ","distractors":["يتبع","عجين","يُلصق"]},{"type":"gap_fill","prompt":"He's the _____.","answer":"groom"},{"type":"meaning_mcq","prompt":"groom","answer":"عريس","distractors":["عادة / تقليد","حسنًا","تهانينا"]},{"type":"gap_fill","prompt":"There are hundreds of _____s!","answer":"guest"},{"type":"meaning_mcq","prompt":"guest","answer":"ضيف","distractors":["يُلصق","عروس","شبعان / ممتلئ"]},{"type":"gap_fill","prompt":"_____ it was late, we went home.","answer":"as"},{"type":"meaning_mcq","prompt":"as","answer":"بما أنّ / كـ","distractors":["قرص فيديو رقمي","عادة / تقليد","يمسك"]},{"type":"gap_fill","prompt":"People _____ weddings in many ways.","answer":"celebrate"},{"type":"meaning_mcq","prompt":"celebrate","answer":"يحتفل","distractors":["بما أنّ / كـ","غرض / هدف","خاتم"]},{"type":"gap_fill","prompt":"Here are some interesting wedding _____s.","answer":"custom"},{"type":"meaning_mcq","prompt":"custom","answer":"عادة / تقليد","distractors":["قرص فيديو رقمي","يمسك","يحتفل"]},{"type":"gap_fill","prompt":"The bride sticks bread _____ to the door.","answer":"dough"},{"type":"meaning_mcq","prompt":"dough","answer":"عجين","distractors":["يتبع","عادة / تقليد","يمسك"]},{"type":"gap_fill","prompt":"They both _____ the knife.","answer":"hold"},{"type":"meaning_mcq","prompt":"hold","answer":"يمسك","distractors":["عروس","عادة / تقليد","يُلصق"]},{"type":"gap_fill","prompt":"They are all for the same _____.","answer":"purpose"},{"type":"meaning_mcq","prompt":"purpose","answer":"غرض / هدف","distractors":["عجين","يتبع","شبعان / ممتلئ"]},{"type":"gap_fill","prompt":"He gives his bride her wedding _____.","answer":"ring"},{"type":"meaning_mcq","prompt":"ring","answer":"خاتم","distractors":["بما أنّ / كـ","تهانينا","يمسك"]},{"type":"gap_fill","prompt":"They stop bad _____s from finding the bride.","answer":"spirit"},{"type":"meaning_mcq","prompt":"spirit","answer":"روح","distractors":["عروس","خاتم","عادة / تقليد"]},{"type":"gap_fill","prompt":"She _____s dough to the front door.","answer":"stick"},{"type":"meaning_mcq","prompt":"stick (v)","answer":"يُلصق","distractors":["شبعان / ممتلئ","يمسك","عريس"]},{"type":"grammar_reorder","grammar":"العروض والردّ عليها","answer":"Would you like another cake?","tokens":["Would","cake","another","like","you"]},{"type":"grammar_reorder","grammar":"العروض والردّ عليها","answer":"Yes, please. I'd love another one!","tokens":["Yes,","one","love","I'd","another","please."]},{"type":"grammar_reorder","grammar":"التعبير عن الغرض: to و in order to","answer":"He's riding round town to receive everyone's congratulations.","tokens":["receive","riding","town","round","everyone's","congratulations","to","He's"]},{"type":"grammar_reorder","grammar":"التعبير عن الغرض: to و in order to","answer":"He gives her a little money in order to show that he will work hard.","tokens":["a","money","her","will","in","gives","He","that","hard","order","he","little","to","show","work"]},{"type":"dialogue_order","lines":["Would you like another cake?","Yes, please. I'd love another one!","No, thanks, Mrs Kamal. I'm full!","Who'd like to watch our cousin's wedding DVD? It's just arrived.","I'd love to.","Hm. I'd prefer to play computer games."]}],"verified":true,"notes":"Vocabulary words, dialogues and grammar points verified against the PDF; Arabic meanings/explanations authored; examples drawn or adapted from the unit text."},{"number":12,"semester":2,"title":"Finding out about names","page":52,"pages":[52,63],"revision":false,"vocabulary":[{"word":"check","arabic":"يتحقّق","example":"I need to check Yasmeen's details.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"counsellor","arabic":"مرشد (تربوي)","example":"I'm your daughter's new counsellor.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"date of birth","arabic":"تاريخ الميلاد","example":"What's your date of birth?","source":"book word box","example_note":"example adapted from the unit text"},{"word":"given name","arabic":"الاسم الأوّل","example":"Could you spell your given name?","source":"book word box","example_note":"example adapted from the unit text"},{"word":"personal details","arabic":"بيانات شخصية","example":"Some personal details are wrong.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"student","arabic":"طالب","example":"Some of our students' details are wrong.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"wrong","arabic":"خاطئ","example":"Is anything wrong?","source":"book word box","example_note":"example adapted from the unit text"},{"word":"zero","arabic":"صفر","example":"My number starts with zero.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"ancestor","arabic":"سَلَف / جدّ قديم","example":"How did our ancestors get their family names?","source":"book word box","example_note":"example adapted from the unit text"},{"word":"begin","arabic":"يبدأ","example":"Let's begin with a call from Emma Baker.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"discuss","arabic":"يناقش","example":"Today, we're discussing people's names.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"Dr","arabic":"د. (دكتور)","example":"We have Dr Julia Romano.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"long ago","arabic":"منذ زمن بعيد","example":"His family were from Haifa long ago.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"once","arabic":"ذات مرّة / في الماضي","example":"My ancestors were once from Rome.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"on the line","arabic":"على الخطّ (الهاتف)","example":"We have Lucy Paris on the line.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"son","arabic":"ابن","example":"John's son became Johnson.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"text message","arabic":"رسالة نصّية","example":"We have a text message from Dan.","source":"book word box","example_note":"example adapted from the unit text"}],"sentences":["Could I speak to her, please?","Could you hold, please?","Could you spell your given name for me, please?","What does it mean?","He asks what his name means."],"dialogues":[{"title":"Period 1 conversation","page":52,"source":"verbatim from Pupil's Book","lines":[{"speaker":"Dad","gender":"m","gender_verified":true,"text":"Hello. Khalid Haifawi speaking."},{"speaker":"Rose","gender":"f","gender_verified":true,"text":"Good evening, Mr Haifawi. I'm Rose Hill, your daughter's new counsellor."},{"speaker":"Dad","gender":"m","gender_verified":true,"text":"Is there a problem?"},{"speaker":"Rose","gender":"f","gender_verified":true,"text":"No, no. But some of our students' personal details are wrong, and I need to check Yasmeen's. I'm also trying to meet everyone, so I want to find a time to see her. Could I speak to her, please?"},{"speaker":"Dad","gender":"m","gender_verified":true,"text":"Of course. Could you hold, please? … Yasmeen, it's for you."},{"speaker":"Dad","gender":"m","gender_verified":true,"text":"It's your new school counsellor. She says some of their student details are wrong, and she needs to check yours. She says she's also trying to meet everyone, so she wants to find a time to see you."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"Thanks, Dad … Hello. Yasmeen speaking. Dad says you need to check my details."},{"speaker":"Rose","gender":"f","gender_verified":true,"text":"Yes, sorry, Yasmeen, but may I check your family name? Is it H-i-g-h-…?"},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"No, it's H-a-i-f-a-w-i."},{"speaker":"Rose","gender":"f","gender_verified":true,"text":"And could you spell your given name for me, please?"},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"Certainly. It's Y-a-s-m-double-e-n."},{"speaker":"Rose","gender":"f","gender_verified":true,"text":"Ah! Not m-i-n at the end. Y-a-s-m-double-e-n. Yasmeen. What a beautiful name! What does it mean?"},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"It's the name of a flower."},{"speaker":"Rose","gender":"f","gender_verified":true,"text":"Like my name – Rose! Nice! Now, here's my next question: When …?"}],"note":"Book has more than two speakers; 'speaker' gives the character. Map to A/B voices by speaker+gender."}],"texts":[{"title":"Did you know? – Names","page":56,"paragraphs":["Today, the radio programme Did you know? is discussing people's names with Dr Julia Romano.","Family names were often place names. Romano means the family were once from Rome. Haifawi means the family were from Haifa long ago.","Some names are work names. Schumacher is German for shoe maker. Farmer and Fisher are work names, too.","About 700 years ago, people started calling an ancestor of Tina Johnson 'John's son'. Parents often hope their children will be like their names. Lucy means 'light'."],"source":"adapted (shortened) from the Pupil's Book reading text"}],"grammar":[{"title":"الكلام المنقول دون تغيير الزمن","explanation":"عند نقل كلامٍ قيل للتوّ نستعمل says (يقول) دون تغيير زمن الفعل، مع تغيير الضمائر حسب المعنى.","examples":["She says she's also trying to meet everyone.","Dad says you need to check my details."]},{"title":"نقل أسئلة Wh-","explanation":"عند نقل السؤال يصبح ترتيب الكلمات كترتيب الجملة الخبرية (الفاعل ثمّ الفعل) دون do/does ودون علامة استفهام.","examples":["He asks what his name means.","He asks where his family were from.","She wants to know when people started using family names."]},{"title":"لغة الهاتف","explanation":"عبارات مهمّة للمكالمات: ... speaking للتعريف بالنفس، Could I speak to …? لطلب شخص، Could you hold, please? للانتظار.","examples":["Hello. Khalid Haifawi speaking.","Could I speak to her, please?","Could you hold, please?"]}],"grammar_en":["Reported statements, no tense shift","Wh- questions reported with a noun form","Reported Wh- questions, no tense shift"],"pronunciation":[{"title":"numbers and spellings","words":[]}],"functions":["reporting statements, questions and responses","telephone language","checking information on the phone","writing a formal letter"],"writing":["writing a business letter"],"task":"Writing a formal letter","seeds":[{"type":"gap_fill","prompt":"I need to _____ Yasmeen's details.","answer":"check"},{"type":"meaning_mcq","prompt":"check","answer":"يتحقّق","distractors":["الاسم الأوّل","ذات مرّة / في الماضي","مرشد (تربوي)"]},{"type":"gap_fill","prompt":"I'm your daughter's new _____.","answer":"counsellor"},{"type":"meaning_mcq","prompt":"counsellor","answer":"مرشد (تربوي)","distractors":["يبدأ","طالب","يتحقّق"]},{"type":"gap_fill","prompt":"What's your _____?","answer":"date of birth"},{"type":"meaning_mcq","prompt":"date of birth","answer":"تاريخ الميلاد","distractors":["منذ زمن بعيد","مرشد (تربوي)","طالب"]},{"type":"gap_fill","prompt":"Could you spell your _____?","answer":"given name"},{"type":"meaning_mcq","prompt":"given name","answer":"الاسم الأوّل","distractors":["منذ زمن بعيد","يبدأ","على الخطّ (الهاتف)"]},{"type":"gap_fill","prompt":"Some _____ are wrong.","answer":"personal details"},{"type":"meaning_mcq","prompt":"personal details","answer":"بيانات شخصية","distractors":["يناقش","سَلَف / جدّ قديم","يبدأ"]},{"type":"gap_fill","prompt":"Some of our _____s' details are wrong.","answer":"student"},{"type":"meaning_mcq","prompt":"student","answer":"طالب","distractors":["سَلَف / جدّ قديم","الاسم الأوّل","يتحقّق"]},{"type":"gap_fill","prompt":"Is anything _____?","answer":"wrong"},{"type":"meaning_mcq","prompt":"wrong","answer":"خاطئ","distractors":["تاريخ الميلاد","الاسم الأوّل","سَلَف / جدّ قديم"]},{"type":"gap_fill","prompt":"My number starts with _____.","answer":"zero"},{"type":"meaning_mcq","prompt":"zero","answer":"صفر","distractors":["يناقش","يتحقّق","على الخطّ (الهاتف)"]},{"type":"gap_fill","prompt":"How did our _____s get their family names?","answer":"ancestor"},{"type":"meaning_mcq","prompt":"ancestor","answer":"سَلَف / جدّ قديم","distractors":["الاسم الأوّل","خاطئ","يبدأ"]},{"type":"gap_fill","prompt":"Let's _____ with a call from Emma Baker.","answer":"begin"},{"type":"meaning_mcq","prompt":"begin","answer":"يبدأ","distractors":["سَلَف / جدّ قديم","على الخطّ (الهاتف)","خاطئ"]},{"type":"gap_fill","prompt":"Today, we're _____ing people's names.","answer":"discuss"},{"type":"meaning_mcq","prompt":"discuss","answer":"يناقش","distractors":["الاسم الأوّل","تاريخ الميلاد","منذ زمن بعيد"]},{"type":"gap_fill","prompt":"We have _____ Julia Romano.","answer":"Dr"},{"type":"meaning_mcq","prompt":"Dr","answer":"د. (دكتور)","distractors":["يناقش","على الخطّ (الهاتف)","خاطئ"]},{"type":"gap_fill","prompt":"His family were from Haifa _____.","answer":"long ago"},{"type":"meaning_mcq","prompt":"long ago","answer":"منذ زمن بعيد","distractors":["د. (دكتور)","ذات مرّة / في الماضي","صفر"]},{"type":"gap_fill","prompt":"My ancestors were _____ from Rome.","answer":"once"},{"type":"meaning_mcq","prompt":"once","answer":"ذات مرّة / في الماضي","distractors":["منذ زمن بعيد","صفر","يناقش"]},{"type":"gap_fill","prompt":"We have Lucy Paris _____.","answer":"on the line"},{"type":"meaning_mcq","prompt":"on the line","answer":"على الخطّ (الهاتف)","distractors":["رسالة نصّية","سَلَف / جدّ قديم","مرشد (تربوي)"]},{"type":"gap_fill","prompt":"John's _____ became Johnson.","answer":"son"},{"type":"meaning_mcq","prompt":"son","answer":"ابن","distractors":["منذ زمن بعيد","طالب","خاطئ"]},{"type":"gap_fill","prompt":"We have a _____ from Dan.","answer":"text message"},{"type":"meaning_mcq","prompt":"text message","answer":"رسالة نصّية","distractors":["يناقش","خاطئ","بيانات شخصية"]},{"type":"grammar_reorder","grammar":"الكلام المنقول دون تغيير الزمن","answer":"She says she's also trying to meet everyone.","tokens":["also","trying","She","says","to","meet","she's","everyone"]},{"type":"grammar_reorder","grammar":"الكلام المنقول دون تغيير الزمن","answer":"Dad says you need to check my details.","tokens":["says","Dad","my","need","check","to","details","you"]},{"type":"grammar_reorder","grammar":"نقل أسئلة Wh-","answer":"He asks what his name means.","tokens":["means","He","his","asks","name","what"]},{"type":"grammar_reorder","grammar":"نقل أسئلة Wh-","answer":"He asks where his family were from.","tokens":["family","He","from","where","asks","were","his"]},{"type":"grammar_reorder","grammar":"لغة الهاتف","answer":"Hello. Khalid Haifawi speaking.","tokens":["speaking","Haifawi","Khalid","Hello."]},{"type":"grammar_reorder","grammar":"لغة الهاتف","answer":"Could I speak to her, please?","tokens":["I","please","to","her,","speak","Could"]},{"type":"dialogue_order","lines":["Hello. Khalid Haifawi speaking.","Good evening, Mr Haifawi. I'm Rose Hill, your daughter's new counsellor.","Is there a problem?","No, no. But some of our students' personal details are wrong, and I need to check Yasmeen's. I'm also trying to meet everyone, so I want to find a time to see her. Could I speak to her, please?","Of course. Could you hold, please? … Yasmeen, it's for you.","It's your new school counsellor. She says some of their student details are wrong, and she needs to check yours. She says she's also trying to meet everyone, so she wants to find a time to see you."]}],"verified":true,"notes":"Vocabulary words, dialogues and grammar points verified against the PDF; Arabic meanings/explanations authored; examples drawn or adapted from the unit text."},{"number":13,"semester":2,"title":"When Islam came to Spain","page":64,"pages":[64,75],"revision":false,"vocabulary":[{"word":"housework","arabic":"أعمال المنزل","example":"I have to help do the housework.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"hurry up","arabic":"يُسرع","example":"I want to hurry up and finish today.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"look up","arabic":"يبحث عن (في كتاب/قاموس)","example":"I'll look up my History of Islam.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"Muslim","arabic":"مسلم","example":"Muslims from North Africa arrived in 711.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"pick up","arabic":"يلتقط / يرفع","example":"He picks up his phone.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"put down","arabic":"يضع","example":"He puts down his pen.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"take over","arabic":"يسيطر على / يتولّى","example":"They took over the country.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"turn off","arabic":"يُطفئ","example":"Turn off your computer.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"work on","arabic":"يعمل على","example":"What are you working on now?","source":"book word box","example_note":"example adapted from the unit text"},{"word":"Islam","arabic":"الإسلام","example":"When Islam came to Spain","source":"book word box","example_note":"example adapted from the unit text"},{"word":"Islamic","arabic":"إسلامي","example":"My project is about Islamic Spain.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"architecture","arabic":"فنّ العمارة","example":"Its architecture became famous.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"disease","arabic":"مرض","example":"Al-Khatib found out how people pass diseases on.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"land","arabic":"أرض","example":"They changed the land they called Al-Andalus.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"medical","arabic":"طبّي","example":"Al-Zahrawi worked out new medical operations.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"operation","arabic":"عملية (جراحية)","example":"He worked out many new operations.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"rich","arabic":"غنيّ","example":"Al-Andalus soon grew rich.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"set up","arabic":"يؤسّس","example":"They set up their capital in Cordoba.","source":"book word box","example_note":"example adapted from the unit text"},{"word":"work out","arabic":"يتوصّل إلى / يبتكر","example":"He worked out new medical operations.","source":"book word box","example_note":"example adapted from the unit text"}],"sentences":["Is anything wrong?","Poor you!","What are you working on now?","I'll look up my History of Islam.","Turn off your computer. It's late!"],"dialogues":[{"title":"Period 1 conversation","page":64,"source":"verbatim from Pupil's Book","lines":[{"speaker":"Sami","gender":"m","gender_verified":true,"text":"Hi, Mike? Is anything wrong? You didn't play football with us after school."},{"speaker":"Mike","gender":"m","gender_verified":true,"text":"I couldn't. I've got lots of homework."},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"What about doing that tomorrow? It's Saturday."},{"speaker":"Mike","gender":"m","gender_verified":true,"text":"No, I want to hurry up and finish today if I can."},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"But why?"},{"speaker":"Mike","gender":"m","gender_verified":true,"text":"We've got some visitors tomorrow, so I have to get up early and help do the housework. I have to tidy up my room, sweep up round the house – and help with the guests, too!"},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"Poor you! So what are you working on now?"},{"speaker":"Mike","gender":"m","gender_verified":true,"text":"My project about Islamic Spain."},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"Oh, yes, when Muslims from North Africa took Spain."},{"speaker":"Mike","gender":"m","gender_verified":true,"text":"Yes, they took over the country, and I need to find out the date."},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"I can help. I'll look up my History of Islam here."},{"speaker":"Mike","gender":"m","gender_verified":true,"text":"Oh, thanks!"},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"I'm looking for the right place. Islamic art … Islamic culture … Ah! Islamic Spain!"},{"speaker":"Mike","gender":"m","gender_verified":true,"text":"Well done!"},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"Here it is. Listen, the Muslims arrived in the year 711, and they stayed for almost 800 years."},{"speaker":"Mike","gender":"m","gender_verified":true,"text":"Thanks, Sami!"},{"speaker":"Sami","gender":"m","gender_verified":true,"text":"And now I think you should turn off your computer and stop. It's late!"}],"note":"Book has more than two speakers; 'speaker' gives the character. Map to A/B voices by speaker+gender."}],"texts":[{"title":"The Muslims in Al-Andalus","page":68,"paragraphs":["In Spain, East and West met for almost 800 years. The Muslims arrived in 711 and took the country over very quickly.","They came with new crops and better ways of farming, and Al-Andalus soon grew rich. They set up their capital in Cordoba and built beautiful mosques and palaces.","Al-Andalus became a centre of the Islamic World. Al-Khatib found out how people pass diseases on, and Al-Zahrawi worked out many new medical operations.","Today, in old Cordoba and at the Alhambra Palace in Granada, ancient Al-Andalus still lives."],"source":"adapted (shortened) from the Pupil's Book reading text"}],"grammar":[{"title":"الأفعال المركّبة (الفعل + حرف)","explanation":"بعض الأفعال المركّبة لا تأخذ مفعولًا (hurry up). وبعضها يأخذ مفعولًا يأتي بعد الحرف أو بينهما (turn off the computer / turn the computer off)، أمّا إذا كان المفعول ضميرًا فيأتي بين الفعل والحرف فقط (turn it off).","examples":["I want to hurry up and finish.","He puts down his pen and picks up his phone.","They took the country over very quickly.","Turn off your computer."]}],"grammar_en":["Two-part (phrasal) verbs with no object","Two-part verbs with object noun in final position","Two-part verbs with object noun in middle or final position, object pronoun in middle position only"],"pronunciation":[{"title":"rhyming words","words":[]}],"functions":["finding out about personal routines","describing a famous Palestinian building"],"writing":["topic sentences"],"task":"Describing a famous Palestinian building","seeds":[{"type":"gap_fill","prompt":"I have to help do the _____.","answer":"housework"},{"type":"meaning_mcq","prompt":"housework","answer":"أعمال المنزل","distractors":["يعمل على","أرض","إسلامي"]},{"type":"gap_fill","prompt":"I want to _____ and finish today.","answer":"hurry up"},{"type":"meaning_mcq","prompt":"hurry up","answer":"يُسرع","distractors":["طبّي","يتوصّل إلى / يبتكر","أعمال المنزل"]},{"type":"gap_fill","prompt":"I'll _____ my History of Islam.","answer":"look up"},{"type":"meaning_mcq","prompt":"look up","answer":"يبحث عن (في كتاب/قاموس)","distractors":["يسيطر على / يتولّى","أعمال المنزل","عملية (جراحية)"]},{"type":"gap_fill","prompt":"_____s from North Africa arrived in 711.","answer":"Muslim"},{"type":"meaning_mcq","prompt":"Muslim","answer":"مسلم","distractors":["يلتقط / يرفع","يضع","مرض"]},{"type":"meaning_mcq","prompt":"pick up","answer":"يلتقط / يرفع","distractors":["عملية (جراحية)","مسلم","طبّي"]},{"type":"meaning_mcq","prompt":"put down","answer":"يضع","distractors":["الإسلام","مسلم","يُسرع"]},{"type":"meaning_mcq","prompt":"take over","answer":"يسيطر على / يتولّى","distractors":["يبحث عن (في كتاب/قاموس)","إسلامي","يضع"]},{"type":"gap_fill","prompt":"_____ your computer.","answer":"turn off"},{"type":"meaning_mcq","prompt":"turn off","answer":"يُطفئ","distractors":["طبّي","فنّ العمارة","يُسرع"]},{"type":"meaning_mcq","prompt":"work on","answer":"يعمل على","distractors":["طبّي","فنّ العمارة","يُسرع"]},{"type":"gap_fill","prompt":"When _____ came to Spain","answer":"Islam"},{"type":"meaning_mcq","prompt":"Islam","answer":"الإسلام","distractors":["يؤسّس","أعمال المنزل","يلتقط / يرفع"]},{"type":"gap_fill","prompt":"My project is about _____ Spain.","answer":"Islamic"},{"type":"meaning_mcq","prompt":"Islamic","answer":"إسلامي","distractors":["غنيّ","يلتقط / يرفع","عملية (جراحية)"]},{"type":"gap_fill","prompt":"Its _____ became famous.","answer":"architecture"},{"type":"meaning_mcq","prompt":"architecture","answer":"فنّ العمارة","distractors":["يلتقط / يرفع","يعمل على","غنيّ"]},{"type":"gap_fill","prompt":"Al-Khatib found out how people pass _____s on.","answer":"disease"},{"type":"meaning_mcq","prompt":"disease","answer":"مرض","distractors":["يؤسّس","أرض","يعمل على"]},{"type":"gap_fill","prompt":"They changed the _____ they called Al-Andalus.","answer":"land"},{"type":"meaning_mcq","prompt":"land","answer":"أرض","distractors":["إسلامي","يتوصّل إلى / يبتكر","الإسلام"]},{"type":"gap_fill","prompt":"Al-Zahrawi worked out new _____ operations.","answer":"medical"},{"type":"meaning_mcq","prompt":"medical","answer":"طبّي","distractors":["إسلامي","أعمال المنزل","يسيطر على / يتولّى"]},{"type":"gap_fill","prompt":"He worked out many new _____s.","answer":"operation"},{"type":"meaning_mcq","prompt":"operation","answer":"عملية (جراحية)","distractors":["يضع","مرض","الإسلام"]},{"type":"gap_fill","prompt":"Al-Andalus soon grew _____.","answer":"rich"},{"type":"meaning_mcq","prompt":"rich","answer":"غنيّ","distractors":["يضع","يبحث عن (في كتاب/قاموس)","الإسلام"]},{"type":"gap_fill","prompt":"They _____ their capital in Cordoba.","answer":"set up"},{"type":"meaning_mcq","prompt":"set up","answer":"يؤسّس","distractors":["الإسلام","يُسرع","يضع"]},{"type":"meaning_mcq","prompt":"work out","answer":"يتوصّل إلى / يبتكر","distractors":["عملية (جراحية)","يعمل على","يلتقط / يرفع"]},{"type":"grammar_reorder","grammar":"الأفعال المركّبة (الفعل + حرف)","answer":"I want to hurry up and finish.","tokens":["hurry","up","finish","want","and","I","to"]},{"type":"grammar_reorder","grammar":"الأفعال المركّبة (الفعل + حرف)","answer":"He puts down his pen and picks up his phone.","tokens":["his","He","and","phone","picks","down","his","pen","puts","up"]},{"type":"dialogue_order","lines":["Hi, Mike? Is anything wrong? You didn't play football with us after school.","I couldn't. I've got lots of homework.","What about doing that tomorrow? It's Saturday.","No, I want to hurry up and finish today if I can.","But why?","We've got some visitors tomorrow, so I have to get up early and help do the housework. I have to tidy up my room, sweep up round the house – and help with the guests, too!"]}],"verified":true,"notes":"Vocabulary words, dialogues and grammar points verified against the PDF; Arabic meanings/explanations authored; examples drawn or adapted from the unit text."},{"number":14,"semester":2,"title":"Revision 2","page":76,"pages":[76,81],"revision":true,"vocabulary":[],"sentences":["The roads will soon get much busier, so we need to go.","I can turn the radio on in order to get the traffic news.","Good idea. If we leave much later, he'll miss his plane! Yasmeen, could you tell the boys we haven't got much time?","And how many kilos has he got? He can only carry 20.","Omar, Dad says if we leave much later, you'll miss your plane."],"dialogues":[{"title":"Revision dialogue: Omar's last day","page":76,"source":"verbatim from Pupil's Book","lines":[{"speaker":"Mr Haifawi","gender":"m","gender_verified":true,"text":"The roads will soon get much busier, so we need to go."},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"I can turn the radio on in order to get the traffic news."},{"speaker":"Mr Haifawi","gender":"m","gender_verified":true,"text":"Good idea. If we leave much later, he'll miss his plane! Yasmeen, could you tell the boys we haven't got much time?"},{"speaker":"Mrs Haifawi","gender":"f","gender_verified":true,"text":"And how many kilos has he got? He can only carry 20."},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"Omar, Dad says if we leave much later, you'll miss your plane."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"OK!"},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"We're coming!"},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"And Mum's asking how many kilos you've got. You can only take 20, she says."},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"Let's check the weight."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Oh, no. It's more than 20. It's 23! I'd better leave some things – things that are heavy. I've got some magazines, and they're heavier than anything else. Would you like them?"},{"speaker":"Adnan","gender":"m","gender_verified":true,"text":"Thanks, but take them in your backpack. You can carry that with you on the plane."},{"speaker":"Omar","gender":"m","gender_verified":true,"text":"Good! I'm ready!"},{"speaker":"Yasmeen","gender":"f","gender_verified":true,"text":"Great! Let's go!"}]}],"texts":[],"grammar":[],"grammar_en":["Revision of Units 8–13"],"pronunciation":[],"functions":["revision of Units 8–13"],"writing":[],"task":"","seeds":[],"verified":false,"notes":"Revision unit: no new word box in the book (vocabulary=[]); dialogue verbatim from p76; exercises in book_exercises."}]};
